/* 포근동행: fictional browser-local prototype. Role switching is a review tool, not authentication. */
(()=>{'use strict';
const E=window.Pogeun;const storage=(()=>{try{return window.localStorage;}catch{return {getItem:()=>null,setItem:()=>{throw new Error('브라우저 저장 공간 사용 불가');}};}})();let activeStudent='s1',activeTutor='t1';let state=E.load(storage),route={},scope='ga',subject='math',tab='student',quiz={key:'',index:0,choice:null,result:null,hint:false,done:false},nationalRegion='all';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 5v16M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2Z',chat:'M21 11a8 8 0 0 1-8 8H8l-5 3 1-6a8 8 0 1 1 17-5Z',users:'M15 21v-3a5 5 0 0 0-5-5H7a5 5 0 0 0-5 5v3M8.5 9a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7ZM17 3a4 4 0 0 1 0 8M17 14a5 5 0 0 1 5 5v2',calendar:'M4 5h16v16H4ZM8 2v6M16 2v6M4 11h16',file:'M6 2h8l5 5v15H6ZM14 2v6h5M9 12h7M9 16h7',chart:'M4 20V10M10 20V4M16 20v-8M22 20H2',check:'m5 12 4 4L19 6',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4M12 18h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',send:'m3 3 19 9-19 9 4-9-4-9Zm4 9h15',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',menu:'M3 6h18M3 12h18M3 18h18',clock:'M12 6v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 4v16M4 12h16',building:'M5 22V3h14v19M9 7h1m4 0h1M9 11h1m4 0h1M9 15h1m4 0h1M10 22v-4h4v4',alert:'M12 8v5m0 4h.01M12 2 1 21h22Z',heart:'M12 21 3 12C-2 5 7-1 12 6c5-7 14-1 9 6Z'};
const icon=(name,size=21)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const roleNames={student:'학생',tutor:'튜터',institution:'기관',central:'중앙 운영자'};
const menus={student:[['today','오늘','home'],['classes','배움방','book'],['questions','질문','chat'],['semester','학기 자료','book']],tutor:[['registration','내 정보·서류','file'],['today','오늘','home'],['classes','클래스','users'],['materials','배포 자료','book'],['semester','학기 자료','book'],['questions','질문함','chat'],['records','학습 기록','chart']],institution:[['today','운영 홈','home'],['students','참여 학생','users'],['matching','튜터·매칭','users'],['schedule','일정·자료','calendar'],['semester','학기 자료','book'],['support','지원','help']],central:[['today','전국 현황','chart'],['institutions','기관 관리','building'],['materials','자료 제작','file'],['agent','교재 에이전트','book'],['semester','학기 자료','book'],['distribution','자료 배포','send'],['support','운영 지원','help']]};
const statusText={scheduled:'수업 예정',active:'수업 중',completed:'수업 완료',cancelled:'취소·보강 필요',waiting:'답변 기다리는 중',answered:'답변 도착',understood:'이해했어요',reasked:'다시 질문했어요',draft:'중앙 초안',review:'내부 검토 중',approved:'배포 준비',published:'중앙 배포',open:'확인 필요',resolved:'조치 완료'};
const status=x=>badge(statusText[x]||x,['completed','understood','resolved','published'].includes(x)?'green':['cancelled','waiting','reasked','open','draft'].includes(x)?'orange':'');
function badge(t,c=''){return `<span class="badge ${c}">${esc(t)}</span>`;}
function btn(t,action,data={},c=''){return `<button type="button" class="button ${c}" data-action="${action}" ${Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${t}</button>`;}
function link(t,view,p={},c='',role=route.role){return `<button type="button" class="button ${c}" data-go="${esc(path(role,view,p))}">${t}</button>`;}
function path(role,view,p={}){const qs=new URLSearchParams(p).toString();return `${role}/${view}${qs?'?'+qs:''}`;}
function go(view,p={},role=route.role){const hash='#'+path(role,view,p);if(location.hash===hash)render();else location.hash=hash;}
function getRoute(){const [raw,query]=location.hash.slice(1).split('?'),[r,v]=raw.split('/');return {role:menus[r]?r:'student',view:v||'today',params:Object.fromEntries(new URLSearchParams(query||''))};}
function findClass(){return state.classes.find(c=>c.id===route.params.id)||state.classes.find(c=>c.students.includes(activeStudent));}
function greetingName(){const n=person(activeStudent).slice(1);return n+((n.charCodeAt(n.length-1)-44032)%28===0?'야':'아');}
function person(id){return state.students.find(s=>s.id===id)?.name||state.tutors.find(t=>t.id===id)?.name||'담당자';}
function institution(id){return state.institutions.find(i=>i.id===id)?.name||'기관';}
function mat(id){return E.material(state,id);}
function classesFor(role=route.role){return state.classes.filter(c=>role==='student'?c.students.includes(activeStudent):role==='tutor'?c.tutor===activeTutor:role==='institution'?c.institution===scope:true);}
function questionsFor(role=route.role){return state.questions.filter(q=>role==='student'?q.student===activeStudent:role==='tutor'?state.classes.find(c=>c.id===q.classId)?.tutor===activeTutor:true);}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4200);}
function commit(action,p,msg,errorTarget){try{const out=E.apply(state,action,p);try{E.save(storage,out.state);}catch{toast('저장 공간에 접근하지 못했어요. 이번 화면에서만 변경이 유지됩니다.');}state=out.state;if(msg)toast(msg);return out;}catch(e){const err=errorTarget||$('#modal[open] .error')||$('.error');if(err)err.textContent=e.message;toast(e.message);return null;}}
function closeModal(){const d=$('#modal');if(d.open)d.close();}
function dialog(title,body){const d=$('#modal');d.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="close" aria-label="닫기" data-action="close">×</button></div><div class="dialog-body">${body}<p class="error" role="alert"></p></div>`;d.showModal();}
function banner(title,text='',kind=''){return `<div class="banner ${kind}">${icon(kind==='orange'?'alert':'book')}<div><strong>${esc(title)}</strong>${esc(text)}</div></div>`;}
function empty(title,text,action=''){return `<div class="empty">${icon('book',32)}<h3>${esc(title)}</h3><p>${esc(text)}</p>${action?`<div class="actions" style="justify-content:center">${action}</div>`:''}</div>`;}
function head(title,desc='',action=''){return `<div class="pagehead"><div><div class="eyebrow">${route.role==='student'?'나의 배움':roleNames[route.role]+' WORKSPACE'}</div><h1 tabindex="-1">${esc(title)}</h1>${desc?`<p class="subline">${esc(desc)}</p>`:''}</div>${action}</div>`;}
function stat(label,n,note,ic='chart',tone=''){return `<div class="stat ${tone}"><div class="row between"><span class="label">${esc(label)}</span><span class="stat-icon">${icon(ic)}</span></div><div class="number">${esc(n)}</div><p class="muted">${esc(note)}</p></div>`;}
function table(headers,rows){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function area(label,name,value='',rows=4,extra=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" name="${name}" rows="${rows}" ${extra}>${esc(value)}</textarea></div>`;}
function select(label,name,options,value,extra=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}" ${extra}>${options.map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`;}
function rowItem(title,desc,action,ic='book'){return `<div class="list-item"><div class="subject-icon">${icon(ic)}</div><div class="list-main"><strong>${esc(title)}</strong><p>${esc(desc)}</p></div>${action}</div>`;}
const bookArt=`<svg class="book-art" viewBox="0 0 260 210" aria-hidden="true"><ellipse cx="135" cy="188" rx="101" ry="13" fill="#b9caf0" opacity=".45"/><path d="M25 54Q80 32 130 65Q180 32 235 54L222 170Q174 149 130 181Q84 149 38 170Z" fill="#3158d5"/><path d="M31 43Q85 27 130 59V165Q84 139 41 158Z" fill="#fff"/><path d="M130 59Q182 26 229 43L218 158Q174 139 130 165Z" fill="#fff7e9"/><path d="M130 61v108" stroke="#c8d6f4" stroke-width="3"/><circle cx="81" cy="97" r="25" fill="#a3b7fa"/><path d="M81 72V97h25A25 25 0 0 0 81 72" fill="#3158d5"/><path d="M153 85h44m-44 18h36m-36 18h40" stroke="#8da4e5" stroke-width="7" stroke-linecap="round"/><path d="m217 17 5 11 12 2-9 8 2 13-10-6-11 6 2-13-9-8 13-2Z" fill="#f4bd63"/><circle cx="22" cy="112" r="11" fill="#9cd5ca"/></svg>`;
function fraction(){return `<div class="fraction-bars"><div class="fraction-demo"><strong>2/3</strong><div class="fraction-bar" aria-label="같은 전체의 3분의 2">${[1,1,0].map(x=>`<span class="${x?'filled':''}"></span>`).join('')}</div></div><div class="fraction-demo"><strong>3/4</strong><div class="fraction-bar" aria-label="같은 전체의 4분의 3">${[1,1,1,0].map(x=>`<span class="${x?'filled':''}"></span>`).join('')}</div></div></div>`;}
function nav(role,mobile=false){return menus[role].map(([v,n,ic])=>`<button class="navlink ${route.view===v||v==='classes'&&['lesson','review','records'].includes(route.view)&&role==='student'||v==='semester'&&['material','practice'].includes(route.view)?'active':''}" data-go="${path(role,v)}" ${route.view===v?'aria-current="page"':''}>${icon(ic)}<span>${n}</span></button>`).join('');}

/* Guided demo state records a starting point; completion always comes from real app records. */
const TOUR_KEY='pogeun-guided-demo-v1';
let guidedTour=(()=>{try{const x=JSON.parse(storage.getItem(TOUR_KEY)||'null');return x?.hidden?{hidden:true}:x&&['learning','operations'].includes(x.kind)&&['questions','materials','classes'].every(k=>Array.isArray(x[k]))&&Number.isInteger(x.attemptCount)?x:null;}catch{return null;}})();
function saveTour(){try{storage.setItem(TOUR_KEY,JSON.stringify(guidedTour));}catch{}}
function startTour(kind){if(!authSession?.demo)return;guidedTour={kind,questions:state.questions.map(q=>q.id),materials:state.materials.map(m=>m.id),classes:state.classes.map(c=>c.id),attemptCount:state.attempts.length};saveTour();activeStudent='s1';activeTutor='t1';scope='ga';quiz.key='';tourNavigate(0);}
function tourSteps(){
 if(!guidedTour||guidedTour.hidden)return [];
 if(guidedTour.kind==='learning'){
  const q=state.questions.find(q=>q.student==='s1'&&q.classId==='cl-m'&&!guidedTour.questions.includes(q.id));
  return [
   {title:'복습 문제 풀기',role:'student',view:'review',params:{id:'cl-m'},button:'답 고르기 → 답 확인하기',detail:'이지우 학생의 수학 복습에서 답을 하나 골라 확인해요.',result:'새 복습 시도가 학습 기록에 저장됐어요.',done:state.attempts.slice(guidedTour.attemptCount).some(a=>a.student==='s1'&&a.classId==='cl-m')},
   {title:'막힌 부분 질문하기',role:'student',view:'review',params:{id:'cl-m'},button:'선생님께 질문',detail:'복습 문제 아래 질문 버튼에서 궁금한 점을 보내요.',result:'새 질문이 튜터 질문함에 도착했어요.',done:!!q},
   {title:'튜터가 답변하기',role:'tutor',view:'questions',params:q?{q:q.id}:{},button:'답변 보내기',detail:'김민서 튜터로 바꾸어 방금 보낸 질문에 설명을 남겨요.',result:'튜터의 답변이 학생에게 전달됐어요.',done:!!q?.messages.some(m=>m.by==='tutor')},
   {title:'이해 여부 확인하기',role:'student',view:'questions',params:q?{q:q.id}:{},button:'이해했어요',detail:'이지우 학생으로 돌아와 답변을 읽고 이해 여부를 표시해요.',result:'질문이 이해 완료 상태로 기록됐어요.',done:q?.status==='understood'}
  ];
 }
 const m=state.materials.find(m=>m.agent&&!guidedTour.materials.includes(m.id));
 const c=state.classes.find(c=>c.institution==='ga'&&!guidedTour.classes.includes(c.id)&&c.status!=='cancelled');
 const delivery=m&&state.deliveries.find(d=>d.materialId===m.id&&d.institution==='ga');
 return [
  {title:'기관에서 클래스 만들기',role:'institution',view:'matching',params:{},button:'자동매칭안 만들기 → 기관 최종 승인',detail:'가온센터의 미배정 학생 후보를 만들고 참여 의사를 확인한 뒤 승인해요. 이미 배정됐다면 직접 구성에서 새 수업을 만들 수 있어요.',result:'새 클래스가 기관 수업 일정에 등록됐어요.',done:!!c},
  {title:'교재 꾸러미 생성하기',role:'central',view:'agent',params:{},button:'교재 꾸러미 생성·점검',detail:'앞서 만든 클래스와 같은 과목을 선택해요. 꾸러미는 학생 교재·복습 문제·튜터 지도안을 함께 묶은 자료예요.',result:'새 교재와 자동 점검 결과가 만들어졌어요.',done:!!m},
  {title:'내용 검토·승인하기',role:'central',view:m?'editor':'agent',params:m?{id:m.id}:{},button:'내부 검토로 넘기기 → 4개 항목 확인 → 검토 완료·배포 준비',detail:'오류를 수정하고 개념·문제·정답·지도안을 직접 확인해요. 자동 점검만으로 승인되지 않아요.',result:'중앙 검토를 마친 자료가 배포 준비 상태예요.',done:!!m?.reviewed&&['approved','published'].includes(m.status)},
  {title:'가온센터에 배포하기',role:'central',view:'distribution',params:m?{id:m.id}:{},button:'가온센터 선택 → 선택한 기관에 배포',detail:'배포는 기관 자료함에 전달하는 단계예요. 학생 수업 연결은 기관이 진행해요.',result:'가온센터 자료함에 새 자료가 도착했어요.',done:!!delivery},
  {title:'기관에서 수신 확인하기',role:'institution',view:'schedule',params:{},button:'배포 자료 → 수신 확인하기',detail:m?'방금 만든 「'+m.title+'」의 수신을 확인해요.':'중앙에서 배포한 새 자료를 확인해요.',result:'기관의 자료 수신이 확인됐어요.',done:!!delivery?.received},
  {title:'새 클래스에 연결하기',role:'institution',view:'schedule',params:{},button:'클래스에 연결 → 새 클래스 선택 → 자료 연결하기',detail:c?'「'+c.name+'」에 같은 과목 자료를 연결해요.':'앞서 만든 예정 클래스에 같은 과목 자료를 연결해요.',result:'새 클래스에 교재가 연결되어 학생·튜터 수업에서 볼 수 있어요.',done:!!m&&!!c&&c.materialId===m.id}
 ];
}
function tourNavigate(index){if(!authSession?.demo)return;const steps=tourSteps(),step=steps[index]||steps.find(s=>!s.done)||steps[steps.length-1];if(!step)return;closeModal();scope='ga';activeStudent='s1';activeTutor='t1';if(step.role==='tutor'){const q=state.questions.find(q=>q.id===step.params.q);activeTutor=state.classes.find(c=>c.id===q?.classId)?.tutor||'t1';}if(step.role==='institution'&&step.view==='schedule')tab='materials';go(step.view,step.params,step.role);}
function tourChoices(){return `<div class="tour-choices"><div><strong>학생·튜터 핵심 체험</strong><p>복습 → 질문 → 답변 → 이해 확인</p>${btn('핵심 체험 시작','startTour',{kind:'learning'},'primary small')}</div><div><strong>기관·중앙 운영 체험</strong><p>클래스 → 꾸러미 → 검토 → 배포·수신 → 연결</p>${btn('운영 체험 시작','startTour',{kind:'operations'},'small')}</div></div>`;}
function guidedTourPanel(){if(!authSession?.demo||guidedTour?.hidden)return '';if(!guidedTour)return `<section class="guided-tour tour-welcome" aria-label="체험 경로 선택"><div class="row between"><strong>어떤 흐름을 체험할까요?</strong>${btn('안내 접기','stopTour',{},'ghost small')}</div>${tourChoices()}</section>`;const steps=tourSteps(),index=steps.findIndex(s=>!s.done),completed=steps.filter(s=>s.done).length,step=steps[index],last=steps.filter(s=>s.done).at(-1);return `<section class="guided-tour" aria-label="체험 진행 안내"><div class="row between"><strong>${guidedTour.kind==='learning'?'학생·튜터 핵심 체험':'기관·중앙 운영 체험'} · ${completed}/${steps.length} 완료</strong><div class="actions">${btn('경로 바꾸기','tour',{},'ghost small')}${btn('안내 닫기','stopTour',{},'ghost small')}</div></div><progress max="${steps.length}" value="${completed}" aria-label="완료한 체험 단계"></progress>${last?`<p class="tour-result">${icon('check',16)} ${esc(last.result)}</p>`:''}${step?`<div class="tour-current"><div>${badge((index+1)+'단계 · '+roleNames[step.role])}<h2>${esc(step.title)}</h2><p>${esc(step.detail)}</p><p class="muted">누를 버튼: ${esc(step.button)}</p><p class="muted">현재 역할: ${roleNames[route.role]}${route.role!==step.role?' · 아래 버튼으로 역할과 화면을 함께 바꿀 수 있어요.':''}</p>${steps[index+1]?`<p class="muted">다음: ${esc(steps[index+1].title)}</p>`:''}</div>${btn('이 단계 열기 '+icon('arrow',15),'tourStep',{index},'primary')}</div>`:`<p class="tour-result"><strong>모든 단계가 실제 기록으로 확인됐어요.</strong></p>${tourChoices()}`}<details class="tour-checklist"><summary>전체 단계와 완료 결과</summary><ol>${steps.map((s,i)=>`<li class="${s.done?'done':''}"><span>${s.done?'✓ 완료':'○ 대기'} · ${esc(s.title)}</span><small>${esc(s.done?s.result:s.detail)}</small>${btn('열기','tourStep',{index:i},'ghost small')}</li>`).join('')}</ol></details></section>`;}
function workflowPanel(m){if(!m)return '';const ds=state.deliveries.filter(d=>d.materialId===m.id),local=ds.find(d=>d.institution===scope),used=state.classes.filter(c=>c.materialId===m.id&&(route.role!=='institution'||c.institution===scope)),approved=m.reviewed&&['approved','published'].includes(m.status),isInstitution=route.role==='institution';const stages=[['중앙 검토','중앙',approved],['기관 배포','중앙',isInstitution?!!local:ds.length>0],['수신 확인','기관',isInstitution?!!local?.received:ds.some(d=>d.received)],['클래스 연결','기관',used.length>0]];let message,action='';if(!approved){message='중앙 검토·승인을 마쳐야 배포할 수 있어요.';if(!isInstitution)action=link('검토 화면 열기','editor',{id:m.id},'small');}else if(!ds.length||isInstitution&&!local){message='해당 기관에 먼저 자료를 배포해 주세요.';if(!isInstitution)action=link('배포 단계 열기','distribution',{id:m.id},'small');}else if(isInstitution&&!local.received){message='기관 수신 확인을 마치면 클래스에 연결할 수 있어요.';action=btn('수신 확인하기','receive',{id:m.id},'small');}else if(isInstitution&&!used.length){const scheduled=classesFor('institution').some(c=>c.status==='scheduled'&&c.subject===m.key);message=scheduled?'수신한 자료를 같은 과목의 예정 클래스에 연결해 주세요.':'같은 과목의 예정 클래스가 없어 연결할 수 없어요.';action=scheduled?btn('클래스에 연결','assignMaterial',{id:m.id},'small'):link('클래스 만들기','matching',{},'small');}else{message=used.length?used.length+'개 클래스에 연결되어 있어요.':'기관이 수신을 확인하고 예정 클래스에 연결하면 학생 수업에 적용돼요.';if(!isInstitution&&authSession?.demo)action=btn('기관 수신 화면 열기','openInstitutionMaterials',{id:ds[0]?.institution||'ga'},'small');}return `<section class="workflow-panel" aria-label="자료 진행 단계"><ol>${stages.map(([title,owner,done])=>`<li class="${done?'done':''}"><strong>${done?'✓ ':''}${title}</strong><small>${owner} 담당 · ${done?'완료':'대기'}</small></li>`).join('')}</ol><div class="row between"><p>${esc(message)}</p>${action}</div></section>`;}
function materialFilterData(items,institutionMode=false){const f={subject:route.params.filterSubject||'',unit:route.params.filterUnit||'',status:route.params.filterStatus||''};return {filters:f,list:items.filter(m=>(!f.subject||m.key===f.subject)&&(!f.unit||(m.unit||'기존 예시')===f.unit)&&(!f.status||(institutionMode?(f.status==='connected'?state.classes.some(c=>c.institution===scope&&c.materialId===m.id):f.status==='received'?state.deliveries.some(d=>d.institution===scope&&d.materialId===m.id&&d.received):state.deliveries.some(d=>d.institution===scope&&d.materialId===m.id&&!d.received)):m.status===f.status)))};}
function materialFilters(items,institutionMode=false){const {filters:f,list}=materialFilterData(items,institutionMode),units=[...new Set(items.filter(m=>!f.subject||m.key===f.subject).map(m=>m.unit||'기존 예시'))],states=institutionMode?[['new','미수신'],['received','수신 완료'],['connected','클래스 연결']]:Object.entries(statusText).filter(([k])=>['draft','review','approved','published'].includes(k));return `<form class="material-filters" data-form="materialFilters" data-context="${institutionMode?'institution':'central'}">${select('과목','filterSubject',[['','전체 과목'],['math','수학'],['english','영어']],f.subject)}${select('단원','filterUnit',[['','전체 단원'],...units.map(u=>[u,u])],f.unit)}${select('상태','filterStatus',[['','전체 상태'],...states],f.status)}<div class="actions"><button type="submit" class="button primary">자료 찾기</button>${btn('필터 초기화','resetMaterialFilters',{context:institutionMode?'institution':'central'})}</div><p class="muted" role="status">${list.length}개 결과 / 전체 ${items.length}개 자료</p></form>`;}

function render(){if(!authSession){closeModal();authView();return;}if(!authSession.demo){if(authSession.role==='student')activeStudent=authSession.personId;if(authSession.role==='tutor')activeTutor=authSession.personId;scope=authSession.institution;}route=getRoute();if(location.hash.startsWith('#auth/')||!authSession.demo&&route.role!==authSession.role){history.replaceState(null,'','#'+authSession.role+'/today');route=getRoute();}document.body.className=route.role;document.title=`포근동행 · ${roleNames[route.role]}`;const isStudent=route.role==='student';const activeName=menus[route.role].find(x=>x[0]===route.view)?.[1]||'상세 보기';const brand=`<a class="brand" href="#${route.role}/today"><span class="brand-icon">${icon('heart',23)}</span>포근동행</a>`;
$('#app').innerHTML=`<div class="demo"><div class="demo-label"><b>PROTOTYPE</b> 예시 데이터 · 브라우저 저장</div><div class="role-switch" aria-label="검토용 역할 전환">${Object.keys(menus).filter(r=>authSession.demo||r===authSession.role).map(r=>`<button data-go="${r}/today" class="${route.role===r?'active':''}" aria-pressed="${route.role===r}">${roleNames[r]}</button>`).join('')}</div><div class="demo-actions">${authSession.demo?'<button data-action="tour">체험 안내</button><button data-action="reset">초기화</button>':''}<button data-action="logout">로그아웃</button></div></div><div class="layout"><aside class="sidebar"><div>${brand}<span class="role-badge">${roleNames[route.role]}</span></div><nav aria-label="주 메뉴">${nav(route.role)}</nav><div class="sidebar-foot">같은 자료로, 함께 자라는 배움<br><button data-action="help">${icon('help',17)} 이용 도움</button><div>초등 5학년 · 수학·영어</div></div></aside><div class="workspace"><header class="topbar">${isStudent?brand:`<button class="button ghost mobile-menu" data-action="menu" aria-label="전체 메뉴">${icon('menu')}</button><span class="crumb">포근동행 <span style="padding:0 12px;color:#a2aec2">/</span> ${activeName}</span>`}${isStudent?`<nav class="student-nav" aria-label="주 메뉴">${nav('student')}</nav>`:''}<div class="user">${route.role==='institution'?`<select aria-label="검토할 소속 기관" id="scope">${state.institutions.filter(i=>authSession.demo||i.id===scope).map(i=>`<option value="${i.id}" ${i.id===scope?'selected':''}>${i.name}</option>`).join('')}</select>`:`<span class="avatar">${isStudent?person(activeStudent).slice(1,2):route.role==='tutor'?person(activeTutor).slice(1,2):'중'}</span>${isStudent||route.role==='tutor'?`<select id="persona" aria-label="체험할 ${isStudent?'학생':'튜터'} 선택">${(isStudent?state.students:state.tutors).filter(p=>authSession.demo||p.id===authSession.personId).map(p=>`<option value="${p.id}" ${p.id===(isStudent?activeStudent:activeTutor)?'selected':''}>${esc(p.name)}${isStudent?' 학생':' 튜터'}</option>`).join('')}</select>`:'<span>중앙 운영팀</span>'}`}<button class="button ghost" data-action="help" aria-label="이용 도움">${icon('help')}</button></div></header><main id="main" tabindex="-1">${guidedTourPanel()}${view()}<div class="footer-note">포근동행 · ${isStudent?'차근차근, 함께 배우는 오늘':'중앙 제작·배포 / 기관 검토·매칭·운영'} <span style="float:right">예시 데이터로 체험 중</span></div></main></div></div>${isStudent?`<nav class="mobile-bottom" aria-label="모바일 주 메뉴">${nav('student',true)}</nav>`:''}`;}
function view(){try{if(route.view==='semester')return semesterLibrary();if(route.view==='material')return semesterDetail();if(route.view==='practice'&&route.role==='student')return reviewView();return route.role==='student'?studentView():route.role==='tutor'?tutorView():route.role==='institution'?institutionView():centralView();}catch(e){console.error(e);return empty('화면을 다시 열어 주세요','선택한 항목을 찾지 못했어요.',link('홈으로','today',{},'primary'));}}
function studentView(){switch(route.view){case 'classes':return head('우리 배움방','수업에서 본 자료로 다시 연습해 봐요.',link('내 학습 기록','records'))+`<div class="grid cols2">${classesFor().map(classCard).join('')}</div>`;case 'lesson':return lessonView(false);case 'review':return reviewView();case 'questions':return questionView(false);case 'records':return recordsView(false);default:return studentHome();}}
function studentHome(){const list=classesFor().filter(c=>c.status!=='cancelled'),english=list.find(x=>x.subject==='english'),c=list.find(c=>c.status!=='completed')||list[0],m=c&&mat(c.materialId),a=questionsFor().find(q=>q.status==='answered');return `<div class="welcome"><div class="welcome-face">☀</div><div><h1>${esc(greetingName())}, 오늘도 같이 해보자!</h1><p class="subline">작은 한 걸음이 모여, 더 큰 배움이 돼.</p></div></div>${c?`<section class="hero"><div class="hero-content"><div class="label">다음 수업</div><h2>${badge(E.lessons[c.subject].subject)} ${esc(m?.title||c.name)}</h2><p>${icon('calendar',19)} ${esc(c.slot)} · ${esc(person(c.tutor))} 선생님</p><p class="muted" style="margin-top:8px">${esc(institution(c.institution))} · ${esc(c.room)}</p>${link('배움방 들어가기 '+icon('arrow'),'lesson',{id:c.id},'primary')}</div>${bookArt}</section>`:banner('배움방을 준비하고 있어요','기관 선생님이 수업이 정해지면 안내해 주실 거예요.')}<div class="grid cols3" style="margin-top:22px"><section class="activity-card lavender"><h3>이어서 복습해요</h3><p class="muted">${esc(m?.title||'배정된 복습을 확인해요.')}</p>${c&&c.reviewAssigned?link('복습 계속하기 '+icon('arrow'),'review',{id:c.id}):link('배움방 보기','classes')}</section><section class="activity-card mint"><h3>${a?'선생님 답변이 왔어요':'궁금한 건 함께 풀어요'}</h3><p class="muted">${esc(a?.messages[0].text||'배운 내용에서 막힌 부분을 질문해 봐요.')}</p>${link(a?'답변 보기 '+icon('arrow'):'내 질문 보기','questions',a?{q:a.id}:{})}</section><section class="activity-card peach"><h3>${english?'영어도 함께 해요':'우리 배움방 둘러보기'}</h3><p class="muted">${english?'하루 일과를 짧은 문장으로 말해 볼까요?':'기관에서 연결한 수업과 자료를 확인해요.'}</p>${english?link('영어 자료 보기 '+icon('arrow'),'lesson',{id:english.id}):link('배움방 보기','classes')}</section></div><section class="card" style="margin-top:24px"><div class="cardhead"><h2>오늘의 작은 발걸음</h2>${link('기록 보기 '+icon('arrow',16),'records',{},'ghost small')}</div><div class="grid cols3">${[['book','수업 자료 살펴보기','오늘의 목표를 확인해요.'],['check','조금씩 복습하기','틀려도 괜찮아요. 다시 해봐요.'],['chat','선생님과 이야기하기','질문은 배움의 시작이에요.']].map(([ic,t,d])=>`<div class="row"><span class="subject-icon">${icon(ic)}</span><div><strong style="font-size:15px">${t}</strong><p class="muted">${d}</p></div></div>`).join('')}</div></section>`;}
function classCard(c){const m=mat(c.materialId);return `<section class="card"><div class="row between">${badge(E.lessons[c.subject].subject,c.subject==='english'?'purple':'')}${status(c.status)}</div><h2 style="margin:20px 0 7px">${esc(c.name)}</h2><p class="muted">${esc(c.slot)} · ${esc(c.room)}</p><div class="divider"></div><p style="font-weight:650">${esc(m?.title||'공통 자료 연결을 기다리고 있어요.')}</p><p class="muted" style="margin-top:7px">${esc(person(c.tutor))} 선생님 · ${esc(institution(c.institution))}</p><div class="actions">${link(route.role==='student'?'자료 보기':'수업 준비하기','lesson',{id:c.id},'primary')}${route.role==='student'&&c.reviewAssigned?link('복습하기','review',{id:c.id}):''}</div></section>`;}
function lessonView(tutor){const c=findClass();if(!c||!classesFor().some(x=>x.id===c.id))return empty('배정된 수업을 선택해 주세요','배움방에서 나의 수업을 찾을 수 있어요.',link('배움방','classes'));const m=mat(c.materialId);if(!m)return head(c.name)+banner('기관에서 자료를 연결하고 있어요','기관의 일정·자료에서 수신한 공통 자료를 연결하면 수업을 준비할 수 있어요.','orange');return head(m.title,`${c.name} · ${c.slot} · ${c.room}`,link(icon('back')+' 목록으로','classes',{},'ghost'))+`<div class="mainaside"><section class="card"><div class="row between">${badge(m.subject)}${tutor?badge('중앙 배포 v'+m.version,'green'):badge('오늘의 배움')}</div>${tutor?`<div class="tabs" style="margin-top:12px">${[['student','학생 자료'],['guide','튜터 지도안'],['review','복습 문제']].map(([k,t])=>btn(t,'lessonTab',{tab:k},tab===k?'active':'')).join('')}</div>`:'<div class="divider"></div>'}${!tutor||tab==='student'?`<h2>오늘의 목표</h2><p class="bodycopy" style="margin-top:13px">${esc(m.goal)}</p>${m.workedExample?'':m.key==='math'?fraction():`<div class="context" style="margin:25px 0;font-size:23px">I get up at seven.<small>나는 7시에 일어나요.</small></div>`}<h3>함께 알아봐요</h3><p class="bodycopy" style="margin-top:14px">${esc(m.explanation)}</p>${learningExtras(m)}`:tab==='guide'?`<h2>가르치기 전에</h2><p class="bodycopy" style="margin:15px 0 22px">${esc(m.guide)}</p><div class="material-steps">${['학습 목표와 지난 질문 확인','개념 설명과 예시 함께 보기','학생이 직접 풀어보기','학생의 설명을 듣고 이해 확인'].map(t=>`<div class="material-step">${t}</div>`).join('')}</div>`:materialQuestions(m)}<div class="actions">${tutor?(c.status==='scheduled'?btn('수업 시작하기','lessonStart',{id:c.id},'primary'):c.status==='active'?btn('수업 마치고 복습 배정','lessonFinish',{id:c.id},'primary'):status(c.status)):(c.reviewAssigned?link('복습 시작하기 '+icon('arrow'),'review',{id:c.id},'primary'):badge('수업 후 복습을 열어 드릴게요','gray'))}${!tutor?btn('선생님께 질문','ask',{class:c.id,material:m.id,item:0}):''}</div></section><aside class="stack"><section class="card"><h3>${tutor?'참여 학생':'우리 선생님'}</h3>${tutor?`<div class="checklist" style="margin-top:17px">${c.students.map(s=>`<label class="checkrow"><input type="checkbox" data-attendance="${s}" data-class="${c.id}" ${c.attendance[s]?'checked':''}><span>${esc(person(s))}<small>출석 확인</small></span></label>`).join('')}</div>`:`<div class="row" style="margin:20px 0"><span class="avatar">${person(c.tutor).slice(1,2)}</span><div><strong>${esc(person(c.tutor))} 선생님</strong><p class="muted">${esc(institution(c.institution))}</p></div></div><p class="muted">모르는 부분은 편하게 질문해요.</p>`}</section><section class="card"><h3>${tutor?'수업 메모':'학습 순서'}</h3>${tutor?`<p class="muted" style="margin:12px 0">${esc(c.notes||'수업을 마칠 때 보충할 내용을 기록해 주세요.')}</p>`:`<div class="material-steps" style="margin-top:15px">${['자료 읽기','복습 문제 풀기','궁금한 점 질문하기'].map(t=>`<div class="material-step">${t}</div>`).join('')}</div>`}</section>${tutor?banner('공통 자료의 원본을 유지해요','추가 설명은 수업 메모에 남기고, 자료 오류는 중앙에 알려 주세요.'):''}</aside></div>`;}
function materialQuestions(m){return `<h2 style="margin-bottom:18px">복습 문제와 해설</h2><div class="stack">${m.questions.map((q,i)=>`<div class="context"><strong>${i+1}. ${esc(q.text)}</strong><ol class="lesson-list">${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol><details><summary>정답·힌트·해설 보기</summary><p class="bodycopy">정답: ${esc(q.options[q.answer])}<br>힌트: ${esc(q.hint)}<br>${esc(q.feedback)}</p></details></div>`).join('')}</div>`;}
function reviewView(){const self=route.view==='practice',c=self?null:findClass(),m=mat(route.params.material||c?.materialId);if(self?(!m||m.catalogId!==E.catalogId):(!c||!c.students.includes(activeStudent)||!c.reviewAssigned||!m||!(m.id===c.materialId||state.questions.some(q=>q.student===activeStudent&&q.classId===c.id&&q.materialId===m.id))))return empty('아직 배정된 복습이 없어요','선생님이 수업을 마치면 다시 와 주세요.',link('배움방으로','classes'));const key=(self?'selfStudy':c.id)+m.id;if(quiz.key!==key){const correct=new Set(state.attempts.filter(a=>a.student===activeStudent&&a.classId===(self?null:c.id)&&a.materialId===m.id&&a.correct).map(a=>a.item));let index=m.questions.findIndex((q,i)=>!correct.has(i));quiz={key,index:index<0?0:index,choice:null,result:null,hint:false,done:false};}if(quiz.done)return `<div class="quiz-wrap"><section class="card completed"><div class="score-circle">${icon('check',43)}</div><h2>오늘도 한 걸음 자랐어요!</h2><p class="muted">${esc(m.title)} 복습을 마쳤어요.<br>다시 보고 싶은 문제는 언제든 연습할 수 있어요.</p><div class="actions" style="justify-content:center">${self?link('학기 자료로','semester',{subject:m.key},'primary'):link('배움방으로','classes',{},'primary')}${btn('한 번 더 연습하기','restartQuiz')}</div></section></div>`;const q=m.questions[quiz.index];return `<div class="quiz-wrap">${head('조금씩, 다시 해봐요',m.title,self?link(icon('back')+' 학습자료','material',{id:m.id},'ghost'):link(icon('back')+' 배움방','lesson',{id:c.id},'ghost'))}${learningRecap(m)}<section class="card quiz"><div class="row between">${badge(m.subject)}<span class="muted">${quiz.index+1} / ${m.questions.length} 문제</span></div><div class="progress"><span style="width:${(quiz.index+1)/m.questions.length*100}%"></span></div><h2>${esc(q.text)}</h2>${m.program==='fraction'&&quiz.index===0?fraction():''}<div class="radio-options" role="group" aria-label="답 선택">${q.options.map((o,i)=>`<button class="option ${quiz.choice===i?'selected':''}" data-action="choice" data-choice="${i}" aria-pressed="${quiz.choice===i}">${esc(o)}</button>`).join('')}</div>${quiz.hint?`<div class="banner" style="margin-top:18px">${icon('help')} ${esc(q.hint)}</div>`:''}${quiz.result!==null?`<div class="feedback ${quiz.result?'':'wrong'}" role="status"><strong>${quiz.result?'잘했어요!':'괜찮아요, 한 번 더 생각해 봐요.'}</strong><p style="margin-top:6px">${esc(quiz.result?q.feedback:q.hint)}</p></div>`:''}<div class="actions">${quiz.result===true?btn(quiz.index===m.questions.length-1?'복습 마치기':'다음 문제 '+icon('arrow'),'nextQuestion',{},'primary wide'):btn('답 확인하기','checkAnswer',{class:c?.id||'',material:m.id},'primary wide')}</div><div class="row between" style="margin-top:15px">${btn('힌트 보기','hint',{},'ghost')}${self?badge('혼자 연습 · 학습 기록에 저장','gray'):btn(icon('chat')+' 선생님께 질문','ask',{class:c.id,material:m.id,item:quiz.index},'ghost')}</div></section></div>`;}
function questionView(tutor){const qs=questionsFor(tutor?'tutor':'student'),q=qs.find(q=>q.id===route.params.q);if(!q)return head(tutor?'답변을 기다리는 질문':'선생님과 나눈 질문',tutor?'학생의 시도와 문제 맥락을 함께 확인해 주세요.':'답변이 도착하면 같이 읽고 다시 풀어 봐요.')+`<section class="card">${qs.length?qs.map(q=>{const m=mat(q.materialId);return rowItem(q.messages[0].text,`${m?.subject} · ${m?.title}${tutor?' · '+person(q.student):''}`,`<div class="row">${status(q.status)}${link(tutor?'답변하기':'질문 보기','questions',{q:q.id})}</div>`,'chat');}).join(''):empty('아직 질문이 없어요','자료나 복습 문제에서 선생님께 질문할 수 있어요.')}</section>`;const m=mat(q.materialId),c=state.classes.find(c=>c.id===q.classId);return head(tutor?'학생 질문에 답변하기':'선생님 답변을 읽어봐요','',link(icon('back')+' 질문 목록','questions',{},'ghost'))+`<div class="mainaside"><section class="card"><div class="row between">${status(q.status)}<span class="muted">${tutor?esc(person(q.student))+' 학생':'내 질문'}</span></div><div class="context" style="margin-top:20px"><strong>${esc(m.title)} · ${q.item+1}번 문제</strong><small>${esc(m.questions[q.item]?.text)} ${tutor?'· 자료 v'+m.version:''}</small></div><div class="thread">${q.messages.map(x=>`<div class="bubble ${x.by}"><small>${x.by==='student'?(tutor?person(q.student):'나'):'선생님'}</small>${esc(x.text)}</div>`).join('')}</div>${tutor?`<form data-form="answer" data-id="${q.id}">${area('설명 작성','answer','',4,'required maxlength="1500" placeholder="정답에 이르는 과정을 학생이 따라갈 수 있도록 설명해 주세요."')}<button class="button primary" type="submit">${icon('send')} 답변 보내기</button><p class="error" role="alert"></p></form>`:q.status==='answered'?`<p style="font-weight:650">이제 조금 이해됐나요?</p><div class="actions">${btn('이해했어요 '+icon('check'),'understood',{id:q.id},'primary')}${btn('아직 어려워요','reask',{id:q.id})}</div>`:q.status==='understood'?(banner('이해했다고 표시했어요','원래 문제로 돌아가 다시 풀어봐요.','green')+btn('다시 질문하기','reask',{id:q.id},'ghost')):banner('선생님 답변을 기다리고 있어요','추가 답변이 오면 질문함에서 확인할 수 있어요.')}<div class="actions">${!tutor?link('원래 문제로 돌아가기','review',{id:c.id,material:q.materialId},'ghost'):btn('중앙에 자료 오류 알리기','materialIssue',{material:m.id,institution:c.institution},'ghost')}</div></section><aside class="card"><h3>질문에 연결된 자료</h3><p style="margin:15px 0">${esc(m.title)}</p><p class="muted">${esc(m.goal)}</p><div class="divider"></div><p class="muted">${tutor?'답변 전송은 이해 완료가 아니에요. 학생의 이해 확인과 재질문을 이어서 살펴봐 주세요.':'아직 어렵다면 다시 질문해도 괜찮아요. 선생님이 다른 방법으로 설명해 줄 거예요.'}</p></aside></div>`;}
function recordsView(tutor){const ids=tutor?[...new Set(classesFor('tutor').flatMap(c=>c.students))]:[activeStudent];return head(tutor?'학습 기록과 다음 보충':'내가 쌓아온 배움',tutor?'참여·복습·이해 확인을 각각 살펴봅니다.':'잘 모르겠던 문제를 다시 풀어본 것도 소중한 기록이에요.')+`<div class="stack">${ids.map(id=>{const at=state.attempts.filter(a=>a.student===id),qs=state.questions.filter(q=>q.student===id);return `<section class="card"><div class="cardhead"><h2>${esc(person(id))}${tutor?' 학생':'의 기록'}</h2>${badge('나의 학습','green')}</div><div class="grid cols3">${stat('학습 시도',at.length,'수업 복습과 혼자 연습한 횟수','file')}${stat('맞혀 본 문제',new Set(at.filter(a=>a.correct).map(a=>a.materialId+a.item)).size,'반복 시도는 한 번만 표시','check','green')}${stat('이해 확인',qs.filter(q=>q.status==='understood').length,'학생이 직접 이해했다고 표시','chat')}</div><div class="divider"></div>${qs.length?qs.map(q=>rowItem(q.messages[0].text,mat(q.materialId)?.title,`${status(q.status)} ${link('질문 보기','questions',{q:q.id},'small')}`,'chat')).join(''):empty('아직 질문 기록이 없어요','복습하면서 궁금한 점을 남겨 보세요.')}</section>`;}).join('')}</div>`;}
function tutorView(){switch(route.view){case 'registration':return authSession?.demo?tutorRegistration():tutorAccountView();case 'classes':return head('나의 클래스','기관에서 배정한 수업을 준비합니다.')+`<div class="grid cols2">${classesFor().map(classCard).join('')}</div>`;case 'lesson':return lessonView(true);case 'materials':return tutorMaterials();case 'questions':return questionView(true);case 'records':return recordsView(true);default:{const cs=classesFor(),pending=questionsFor().filter(q=>['waiting','reasked'].includes(q.status)),c=cs.find(c=>c.status==='scheduled')||cs[0],m=c&&mat(c.materialId);return head('오늘의 수업을 준비해요',person(activeTutor)+' 튜터님, 학생들의 작은 질문에 함께해 주세요.')+`<div class="grid cols3 stat-grid" style="margin-bottom:24px">${stat('담당 클래스',cs.length,'기관에서 확정된 수업','users')}${stat('답변 대기',pending.length,'새 질문과 재질문','chat','orange')}${stat('수업 완료',cs.filter(c=>c.status==='completed').length,'복습 배정까지 마친 수업','check','green')}</div><div class="mainaside"><div class="stack">${c?`<section class="hero"><div class="hero-content"><div class="label">${esc(c.slot)} · ${esc(c.name)}</div><h2>${esc(m?.title||'자료를 기다리고 있어요')}</h2>${m?badge('중앙 배포 v'+m.version,'green'):''}<p class="muted" style="margin-top:15px">학생 자료·지도안·복습 문제를 함께 확인해요.</p>${link('수업 준비하기 '+icon('arrow'),'lesson',{id:c.id},'primary')}</div>${bookArt}</section>`:''}<section class="card"><div class="cardhead"><h2>답변을 기다리는 질문</h2>${link('질문함 보기','questions',{},'ghost small')}</div>${pending.length?pending.map(q=>rowItem(q.messages[0].text,person(q.student)+' · '+mat(q.materialId)?.subject,link('답변하기','questions',{q:q.id},'small'),'chat')).join(''):empty('기다리는 질문이 없어요','다음 수업을 여유 있게 준비해 주세요.')}</section></div><aside class="stack"><section class="card"><h3>수업 전 체크</h3><div class="material-steps" style="margin-top:18px">${['중앙 배포 자료 확인','지난 질문·보충 내용 확인','수업 목표와 활동 준비'].map(t=>`<div class="material-step">${t}</div>`).join('')}</div></section>${banner('공통 자료로 함께 가르쳐요','중앙이 만든 자료를 사용하고, 개선 의견은 자료 화면에서 전달해 주세요.')}</aside></div>`;}}}
function tutorMaterials(){const ins=[...new Set(classesFor('tutor').map(c=>c.institution))],ms=state.materials.filter(m=>m.status==='published'&&state.deliveries.some(d=>d.materialId===m.id&&ins.includes(d.institution)&&d.received));return head('중앙에서 배포한 학습자료','과목별 공통 자료와 지도안을 확인해 주세요.')+banner('같은 자료로, 일관된 수업을','자료 원본은 중앙에서 관리합니다. 튜터는 수업 메모와 자료 개선 의견을 남길 수 있어요.')+`<div class="grid cols2" style="margin-top:22px">${ms.map(m=>`<section class="card"><div class="row between">${badge(m.subject)}${badge('중앙 배포 v'+m.version,'green')}</div><h2 style="margin:18px 0 10px">${esc(m.title)}</h2><p class="muted">${esc(m.goal)}</p><div class="actions">${btn('자료 꾸러미 보기','previewMaterial',{id:m.id},'primary')}${btn('오류·개선 의견','materialIssue',{material:m.id,institution:'ga'})}</div></section>`).join('')}</div>`;}

function unassigned(ins){return state.students.filter(s=>s.institution===ins&&s.consent&&s.subjects.some(sub=>!state.classes.some(c=>c.institution===ins&&c.subject===sub&&c.status!=='cancelled'&&c.students.includes(s.id))));}
function institutionView(){switch(route.view){case 'students':return institutionStudents();case 'matching':return matchingView();case 'schedule':return institutionSchedule();case 'support':return supportView(false);default:{const cs=classesFor(),pending=unassigned(scope),supports=state.supports.filter(t=>t.institution===scope&&t.status==='open'),fresh=state.deliveries.filter(d=>d.institution===scope&&!d.received);return head('오늘의 운영 현황',institution(scope)+' · 소속 학생의 참여와 수업을 함께 살펴보세요.',link(icon('plus')+' 매칭 관리','matching',{},'primary'))+`<div class="grid cols3 stat-grid" style="margin-bottom:24px">${stat('참여 학생',state.students.filter(s=>s.institution===scope).length,'우리 기관 소속','users')}${stat('매칭 필요',pending.length,'참여 확인을 마친 학생','users','orange')}${stat('지원 필요',supports.length,'처리 중인 요청','help','green')}</div><div class="mainaside"><div class="stack"><section class="card"><div class="cardhead"><h2>먼저 확인해 주세요</h2>${badge('기관에서 직접 운영')}</div>${pending.length?rowItem('튜터 매칭이 필요한 학생',pending.map(s=>s.name).join(' · '),link('매칭하기','matching',{},'primary small'),'users'):rowItem('현재 참여 학생의 매칭이 완료됐어요','새 참여자와 일정 변경을 계속 살펴보세요.',badge('확인 완료','green'),'check')}${fresh.map(d=>rowItem('새 공통 자료 도착',mat(d.materialId).title+' v'+mat(d.materialId).version,btn('자료 보기','institutionMaterials',{},'small'),'book')).join('')}${supports.slice(0,2).map(t=>rowItem(t.title,t.type,link('지원 확인','support',{id:t.id},'small'),'help')).join('')}</section><section class="card"><div class="cardhead"><h2>우리 기관의 수업</h2>${link('일정 전체 보기','schedule',{},'ghost small')}</div>${classTable(cs,false)}</section></div><aside class="stack">${banner('매칭은 기관에서 검토·확정해요','튜터 자격과 학생 참여 상태, 과목·시간·정원을 확인해 주세요.')}<section class="card"><h3>자료 수신 현황</h3><p class="subline">중앙에서 배포한 공통 자료를 확인해요.</p><div class="number" style="font-size:32px;margin:18px 0">${state.deliveries.filter(d=>d.institution===scope&&d.received).length}<small class="muted"> / ${state.deliveries.filter(d=>d.institution===scope).length}개 수신</small></div>${btn('배포 자료 확인','institutionMaterials',{},'wide')}</section></aside></div>`;}}}
function classTable(cs,central){return cs.length?table(['클래스·일정','담당 튜터','참여','상태',''],cs.map(c=>`<tr><td class="cell-title">${esc(c.name)}<small>${esc(c.slot)} · ${esc(c.room)}</small></td><td>${esc(person(c.tutor))}</td><td>${c.students.length}명</td><td>${status(c.status)}</td><td>${central?badge(c.materialId?'자료 연결':'자료 미연결',c.materialId?'green':'orange'):link('매칭 상세','matching',{id:c.id},'small')}</td></tr>`)):empty('등록된 수업이 없어요','기관에서 튜터와 학생을 연결해 첫 클래스를 만들어 주세요.',central?'':link('매칭하기','matching',{},'primary'));}
function institutionStudents(){const kids=state.students.filter(s=>s.institution===scope);return head('참여 학생',institution(scope)+' 학생의 참여 상태와 배정 수업을 확인합니다.')+`<section class="card">${table(['학생','신청 과목','참여 확인','배정 수업',''],kids.map(s=>`<tr><td class="cell-title">${esc(s.name)}<small>초등 5학년</small></td><td>${s.subjects.map(x=>E.lessons[x].subject).join(' · ')}</td><td>${badge(s.consent?'확인 완료':'확인 필요',s.consent?'green':'orange')}</td><td>${state.classes.filter(c=>c.institution===scope&&c.status!=='cancelled'&&c.students.includes(s.id)).map(c=>esc(c.name)).join(', ')||'미배정'}</td><td>${btn('상세 보기','studentDetail',{id:s.id},'small')}</td></tr>`))}</section><div style="margin-top:20px">${banner('참여 확인 상태를 먼저 확인해요','이 시안의 확인 상태는 예시입니다. 확인 미완료 학생은 매칭 확정 대상에서 제외됩니다.')}</div>`;}
function manualMatchingView(){const c=state.classes.find(c=>c.id===route.params.id&&c.institution===scope),sub=c?.subject||subject;const tutors=state.tutors.filter(t=>t.institution===scope),kids=state.students.filter(s=>s.institution===scope&&s.subjects.includes(sub));const chosen=c?.tutor||tutors.find(t=>t.id==='t2'&&t.subjects.includes(sub))?.id||tutors.find(t=>t.subjects.includes(sub))?.id||'';return head(c?'기관에서 매칭 변경하기':'튜터와 학생을 연결해요','조건을 검토한 뒤 기관 담당자가 매칭을 확정합니다.',c?link('새 매칭 만들기','matching',{},'ghost'):'')+`<div class="mainaside"><section class="card"><div class="cardhead"><h2>${c?esc(c.name):'새 클래스 구성'}</h2>${badge('기관 확정')}</div><form data-form="match" data-id="${c?.id||''}">${field('클래스 이름','name',c?.name||(sub==='math'?'수학 C반':'영어 새 클래스'),'text','required maxlength="40" '+(c?'readonly':''))}<div class="grid cols2">${select('과목','subject',[['math','수학'],['english','영어']],sub,c?'disabled':'data-match-subject')}${select('수업 시간','slot',[['화요일 16:00','화요일 16:00'],['목요일 17:00','목요일 17:00']],c?.slot||'목요일 17:00')}</div>${field('수업 장소','room',c?.room||'학습실 1','text','required maxlength="40"')}${select('담당 튜터','tutor',[['','튜터를 선택해 주세요'],...tutors.map(t=>[t.id,`${t.name} · ${t.subjects.map(x=>E.lessons[x].subject).join('/')} · ${t.verified?'자격 확인':'자격 미확인'} · ${t.slots.join(', ')}`])],chosen,'required')}<fieldset class="field" style="border:0;padding:0"><legend>참여 학생 <small class="muted">최대 4명 · 예시 정원</small></legend><div class="checklist">${kids.map(s=>`<label class="checkrow"><input type="checkbox" name="students" value="${s.id}" ${c?.students.includes(s.id)?'checked':''} ${!s.consent?'disabled':''}><span class="grow">${esc(s.name)}<small>초등 5학년 · ${s.consent?'참여 확인 완료':'참여 확인 전에는 배정할 수 없어요'}</small></span>${badge(s.consent?'확인 완료':'확인 필요',s.consent?'green':'orange')}</label>`).join('')}</div></fieldset><div class="banner">${icon('check')}<div>확정할 때 자격·과목·가능 시간·참여 확인·정원·중복 일정을 함께 확인합니다.</div></div><p class="error" role="alert"></p><div class="actions"><button type="submit" class="button primary">${c?'변경·재배정 확정하기':'매칭 확정하기'} ${icon('check')}</button></div></form></section><aside class="stack"><section class="card"><h3>기관 검토 순서</h3><div class="material-steps" style="margin-top:18px">${['튜터 자격·담당 과목 확인','학생 참여 상태 확인','가능 시간·정원·장소 확인','기관에서 확정하고 안내'].map(t=>`<div class="material-step">${t}</div>`).join('')}</div></section>${banner('중앙은 현황을 확인하고 지원해요','일반 매칭과 변경·재배정은 해당 기관이 검토하고 확정합니다.')}<section class="card"><h3>기존 클래스</h3>${classesFor().map(c=>rowItem(c.name,c.slot,link('변경','matching',{id:c.id},'small'),'users')).join('')||'<p class="subline">아직 클래스가 없어요.</p>'}</section></aside></div>`;}
function institutionSchedule(){const allDeliveries=state.deliveries.filter(d=>d.institution===scope),allMaterials=allDeliveries.map(d=>mat(d.materialId)),filtered=materialFilterData(allMaterials,true).list,ms=allDeliveries.filter(d=>filtered.some(m=>m.id===d.materialId));return head('일정과 공통 학습자료',institution(scope)+'의 수업 일정과 중앙에서 받은 자료를 관리합니다.')+`<div class="tabs">${btn('수업 일정','institutionTab',{tab:'schedule'},tab!=='materials'?'active':'')}${btn('배포 자료','institutionTab',{tab:'materials'},tab==='materials'?'active':'')}</div>${tab==='materials'?`${materialFilters(allMaterials,true)}<div class="stack">${ms.length?ms.map(d=>{const m=mat(d.materialId),cs=classesFor().filter(c=>c.materialId===m.id);return `<section class="card"><div class="row between"><div class="row">${badge(m.subject)}${badge('v'+m.version)}${badge(d.received?'수신 확인':'새 자료',d.received?'green':'orange')}</div><span class="muted">${cs.length}개 클래스에서 사용</span></div><h2 style="margin:20px 0 8px">${esc(m.title)}</h2><p class="muted">${esc(m.goal)}</p>${workflowPanel(m)}<div class="actions">${btn('자료 보기','previewMaterial',{id:m.id})}${d.received&&cs.length?btn('클래스에 연결','assignMaterial',{id:m.id},'primary'):''}</div></section>`;}).join(''):empty(allDeliveries.length?'조건에 맞는 자료가 없어요':'배포된 자료가 없어요',allDeliveries.length?'과목·단원·상태 조건을 바꾸거나 필터를 초기화해 주세요.':'중앙에서 기관에 배포하면 이곳에 표시됩니다.',btn('필터 초기화','resetMaterialFilters',{context:'institution'}))}</div>`:`<div class="stack">${classesFor().length?classesFor().map(c=>`<section class="card"><div class="row between"><h2>${esc(c.name)}</h2>${status(c.status)}</div><p class="subline">${esc(c.slot)} · ${esc(c.room)} · ${esc(person(c.tutor))} 튜터</p><div class="divider"></div><div class="row between"><div><strong>${esc(mat(c.materialId)?.title||'자료 연결 필요')}</strong><p class="muted">${c.materialId?'중앙 배포 v'+mat(c.materialId).version:'배포 자료 탭에서 수신한 자료를 연결해 주세요.'}</p></div>${c.status==='scheduled'?btn('자료 연결','pickMaterial',{class:c.id}):''}</div><div class="actions">${link('매칭·시간 변경','matching',{id:c.id})}${c.status==='scheduled'?btn('수업 취소·보강 검토','cancelClass',{id:c.id},'danger'):c.status==='cancelled'?link('보강 일정 확정','matching',{id:c.id},'primary'):''}</div></section>`).join(''):empty('예정된 수업이 없어요','먼저 튜터와 학생을 매칭해 주세요.',link('매칭하기','matching',{},'primary'))}</div>`}`;}
function flagsFor(i){const f=[];if(unassigned(i).length)f.push('매칭 대기 '+unassigned(i).length+'명');const cancelled=state.classes.filter(c=>c.institution===i&&c.status==='cancelled').length;if(cancelled)f.push('수업 공백 '+cancelled+'건');const ds=state.deliveries.filter(d=>d.institution===i&&!d.received).length;if(ds)f.push('자료 미수신 '+ds+'건');const ss=state.supports.filter(s=>s.institution===i&&s.status==='open').length;if(ss)f.push('지원 진행 '+ss+'건');return f;}
function centralView(){switch(route.view){case 'institutions':return centralInstitutions();case 'materials':return centralMaterials();case 'agent':return materialAgentView();case 'editor':return materialEditor();case 'distribution':return distributionView();case 'support':return supportView(true);default:return centralHome();}}
function centralHome(){const list=state.institutions.filter(i=>nationalRegion==='all'||i.region===nationalRegion),ins=list.map(i=>i.id),ds=state.deliveries.filter(d=>ins.includes(d.institution)),issues=list.filter(i=>flagsFor(i.id).length);return head('전국 프로그램 운영 현황','기관별 운영 상황을 확인하고 필요한 지원을 연결합니다.',link(icon('plus')+' 학습자료 만들기','materials',{},'primary'))+`<div class="filterbar"><select class="filter" id="national-region" aria-label="지역 선택"><option value="all">전국</option>${[...new Set([...state.institutions.map(i=>i.region),'전남','경남','경북','제주','충북','충남'])].map(region=>`<option value="${esc(region)}" ${nationalRegion===region?'selected':''}>${esc(region)}</option>`).join('')}</select><span class="badge gray">예시 운영 기간 전체</span><span class="muted">기관별 마지막 보고 시점은 상세에서 확인</span></div><div class="grid cols3 stat-grid" style="margin-bottom:24px">${stat('운영 기관',list.length,'선택한 지역에 등록된 기관','building')}${stat('확인 필요 기관',issues.length,'매칭·수업·자료·지원 상태','alert','orange')}${stat('자료 수신',ds.filter(d=>d.received).length+' / '+ds.length,'기관별 자료 배포 건 기준','send','green')}</div><div class="mainaside"><div class="stack"><section class="card"><div class="cardhead"><h2>확인이 필요한 기관</h2>${link('기관 전체 보기','institutions',{},'ghost small')}</div>${issues.length?table(['기관','확인할 상황','최근 보고',''],issues.map(i=>`<tr><td class="cell-title">${esc(i.name)}<small>${i.region}</small></td><td>${flagsFor(i.id).map(f=>`<div style="margin:3px 0">${badge(f,'orange')}</div>`).join('')}</td><td>${i.reported}</td><td>${link('기관 확인','institutions',{id:i.id},'small')}</td></tr>`)):list.length?empty('현재 확인 필요 항목이 없어요','최근 보고 시점과 기관의 실제 상황을 함께 확인해 주세요.'):empty('등록된 운영 기관이 없어요','선택한 지역에 기관이 등록되면 운영 현황이 표시됩니다.')}</section><section class="card"><div class="cardhead"><h2>자료 배포와 수신</h2>${link('배포 현황 보기','distribution',{},'ghost small')}</div>${list.length?state.materials.filter(m=>m.status==='published').map(m=>{const d=ds.filter(d=>d.materialId===m.id);return rowItem(m.title+' v'+m.version,`배포 ${d.length} · 수신 ${d.filter(x=>x.received).length} · 미수신 ${d.filter(x=>!x.received).length}`,link('배포 관리','distribution',{id:m.id},'small'),'book');}).join(''):empty('이 지역의 배포 내역이 없어요','운영 기관이 등록되면 자료 배포·수신 현황을 확인할 수 있습니다.')}</section></div><aside class="stack">${banner('중앙 제작 · 기관 운영','중앙은 공통 자료를 제작·배포합니다. 튜터·학생 매칭은 기관에서 검토하고 확정합니다.')}<section class="card"><h3>최근 운영 기록</h3><div class="timeline" style="margin-top:20px">${state.audit.slice(0,5).map(a=>`<div class="timeline-item">${esc(a.text)}<br><small>${new Date(a.at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||'<p class="muted">프로토타입에서 매칭·배포·수업을 진행하면 기록이 쌓입니다.</p>'}</div></section></aside></div>`;}
function centralInstitutions(){const i=state.institutions.find(i=>i.id===route.params.id);if(!i)return head('전국 기관 관리','기관별 매칭·수업·자료·지원 현황을 확인합니다.')+`<section class="card">${table(['기관','등록 학생','클래스','최근 보고',''],state.institutions.map(i=>`<tr><td class="cell-title">${esc(i.name)}<small>${i.region}</small></td><td>${state.students.filter(s=>s.institution===i.id).length}명</td><td>${state.classes.filter(c=>c.institution===i.id).length}개</td><td>${i.reported}</td><td>${link('운영 상세','institutions',{id:i.id},'small')}</td></tr>`))}</section>`;const cs=state.classes.filter(c=>c.institution===i.id),un=unassigned(i.id);return head(i.name+' 운영 현황',i.region+' · 마지막 보고 '+i.reported,link(icon('back')+' 기관 목록','institutions',{},'ghost'))+`<div class="grid cols3 stat-grid" style="margin-bottom:22px">${stat('등록 학생',state.students.filter(s=>s.institution===i.id).length,'기관 소속','users')}${stat('매칭 필요',un.length,'기관 검토·진행 대상','users','orange')}${stat('수업 공백',cs.filter(c=>c.status==='cancelled').length,'취소 후 보강 확인 필요','calendar')}</div><div class="stack">${banner('매칭은 해당 기관이 진행합니다','중앙은 운영 현황을 조회하고 기관에서 해결하기 어려운 문제를 지원합니다.')}<section class="card"><div class="cardhead"><h2>클래스 운영</h2>${btn('운영 지원 등록','newSupport',{institution:i.id,central:'true'},'primary small')}</div>${classTable(cs,true)}</section><section class="card"><div class="cardhead"><h2>자료 수신·사용</h2>${link('배포 관리','distribution',{},'small')}</div>${state.deliveries.filter(d=>d.institution===i.id).map(d=>rowItem(mat(d.materialId).title+' v'+mat(d.materialId).version,`${cs.filter(c=>c.materialId===d.materialId).length}개 클래스 사용`,badge(d.received?'수신 확인':'미수신',d.received?'green':'orange'),'book')).join('')||'<p class="muted">아직 배포된 자료가 없습니다.</p>'}</section></div>`;}
// Central lesson-package workflow. All generated content remains a reviewable draft.
function agentSources(){return state.materials.filter(m=>/^pg5-s1-[me]\d{2}$/.test(m.id)&&m.status==='published').sort((a,b)=>a.week-b.week);}
function materialAgentView(){
 const all=agentSources(),source=all.find(m=>m.id===route.params.source)||all.find(m=>m.id==='pg5-s1-m11')||all[0];
 if(!source)return empty('참고할 학기 자료가 없어요','학기 자료를 확인해 주세요.',link('학기 자료','semester'));
 const subjects=all.filter(m=>m.key===source.key),units=[...new Set(subjects.map(m=>m.unit))],lessons=subjects.filter(m=>m.unit===source.unit),recent=state.materials.filter(m=>m.agent).slice(0,5);
 return head('교재 꾸러미 제작·검수 에이전트','학습목표를 정하면 학생 교재·복습 문제·튜터 지도안을 함께 구성합니다.',link('제작 자료 목록','materials',{},'ghost'))+
 `<section class="agent-intro"><div><span class="eyebrow">LESSON PACKAGE</span><h2>한 차시의 배움을, 하나의 꾸러미로.</h2><p>수업 설계 → 교재 구성 → 자동 점검 → 중앙 검토</p><p class="muted">수록된 36차시를 참고하는 자동화입니다. 외부 생성형 AI는 연결되어 있지 않습니다.</p></div><div class="agent-intro-mark">${icon('book',48)}<span>교재 + 복습 + 지도안</span></div></section>`+
 `<div class="mainaside agent-creation"><section class="card"><div class="cardhead"><h2>어떤 수업을 만들까요?</h2>${badge('중앙 제작','purple')}</div><form data-form="generateMaterial"><div class="grid cols2">${select('학년','grade',[['5','초등학교 5학년']],'5')}${select('과목','subject',[['math','수학'],['english','영어']],source.key,'data-agent-subject')}</div><div class="grid cols2">${select('단원','unit',units.map(u=>[u,u]),source.unit,'data-agent-unit')}${select('참고할 차시','sourceId',lessons.map(m=>[m.id,m.title]),source.id,'data-agent-source')}</div>${area('학습목표','goal',source.goal,3,'required maxlength="600" data-agent-goal')}<p class="muted agent-form-note">차시를 바꾸면 해당 차시의 목표를 불러옵니다. 직접 바꾼 목표와 자료의 적합성은 중앙 검토에서 확인합니다.</p><div class="grid cols3">${select('수업 시간','duration',[['20','20분'],['40','40분'],['60','60분']],'40')}${select('학습 지원 수준','level',[['기초','기초 · 단계별 도움'],['기본','기본 · 개념과 연습'],['도전','도전 · 이유 설명']],'기본')}${select('복습 문항 수','questionCount',[['3','3문항'],['5','5문항'],['8','8문항']],'5')}</div><p class="muted">현재는 5학년 수학·영어 수록 범위를 지원합니다. 문항이 부족하면 문항 수를 줄여 달라는 안내를 표시합니다.</p><p class="error" role="alert"></p><div class="actions"><button class="button primary" type="submit">${icon('plus')} 교재 꾸러미 생성·점검</button></div></form></section><aside class="stack"><section class="card"><h3>한 번에 만들어지는 자료</h3><div class="material-steps agent-process"><div class="material-step"><div><strong>학생용 교재</strong><small>개념 · 예제 · 활동 · 자기 확인</small></div></div><div class="material-step"><div><strong>복습 문제</strong><small>문항 · 힌트 · 정답 · 해설</small></div></div><div class="material-step"><div><strong>튜터 지도안</strong><small>선수 개념 · 시간 배분 · 지도 포인트</small></div></div><div class="material-step"><div><strong>검토 결과</strong><small>자동 확인 항목 · 사람 확인 항목</small></div></div></div></section>${banner('생성 후에도 중앙 검토가 필요해요','자동 점검은 내용 전체의 정확성이나 교육과정 적합성을 보증하지 않습니다. 승인 전에는 기관에 배포되지 않아요.')} ${recent.length?`<section class="card"><h3>최근 만든 꾸러미</h3><div class="stack" style="margin-top:16px">${recent.map(m=>rowItem(m.title,m.subject+' · '+statusText[m.status],link('열기','editor',{id:m.id},'small'))).join('')}</div></section>`:''}</aside></div>`;
}
function syncAgentForm(form,kind){
 const all=agentSources(),subject=form.elements.subject.value;
 if(kind==='subject'){const units=[...new Set(all.filter(m=>m.key===subject).map(m=>m.unit))];form.elements.unit.innerHTML=units.map(u=>`<option value="${esc(u)}">${esc(u)}</option>`).join('');}
 if(kind!=='source'){const list=all.filter(m=>m.key===subject&&m.unit===form.elements.unit.value);form.elements.sourceId.innerHTML=list.map(m=>`<option value="${esc(m.id)}">${esc(m.title)}</option>`).join('');}
 const source=all.find(m=>m.id===form.elements.sourceId.value);if(source)form.elements.goal.value=source.goal;
}
function agentQuestionEditor(q,i){return `<details class="agent-question"><summary>${i+1}번 · ${esc(q.text)}</summary><div class="agent-question-body">${area('문제','q'+i+'_text',q.text,2,'required maxlength="1500"')}${q.options.map((option,j)=>field('선택지 '+(j+1),'q'+i+'_option'+j,option,'text','maxlength="500"')).join('')}${select('정답 선택지','q'+i+'_answer',[['','정답을 선택해 주세요'],...q.options.map((_,j)=>[String(j),String(j+1)+'번'])],Number.isInteger(q.answer)&&q.answer>=0&&q.answer<q.options.length?String(q.answer):'')}${area('힌트','q'+i+'_hint',q.hint,2,'maxlength="1000"')}${area('정답 해설','q'+i+'_feedback',q.feedback,3,'maxlength="1800"')}</div></details>`;}
function agentCheckItem(c){return `<div class="agent-check ${c.status}"><div><span>${c.status==='error'?'오류':c.status==='warning'?'확인 필요':'자동 확인'}</span><strong>${esc(c.label)}</strong></div><p>${esc(c.detail)}</p></div>`;}
function agentReviewPanel(m){
 const report=m.agent.inspection||E.MaterialAgent.inspect(m),editable=['draft','review'].includes(m.status);
 return `<aside class="stack agent-report"><section class="card"><div class="cardhead"><h2>검토 결과</h2>${badge('자동 점검','purple')}</div><div class="agent-check-counts"><div><strong>${report.passed}</strong><span>자동 확인</span></div><div class="${report.warnings?'warning':''}"><strong>${report.warnings}</strong><span>확인 필요</span></div><div class="${report.errors?'invalid':''}"><strong>${report.errors}</strong><span>오류</span></div></div><p class="muted">저장된 내용 기준 · ${report.inspectedAt?esc(new Date(report.inspectedAt).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})):''}</p><div class="agent-checks">${report.checks.filter(c=>c.status!=='pass').map(agentCheckItem).join('')}</div><details class="agent-details agent-passed"><summary>자동 확인 ${report.passed}개 항목 보기</summary><div class="agent-checks">${report.checks.filter(c=>c.status==='pass').map(agentCheckItem).join('')}</div></details><div class="agent-report-controls"></div><div class="actions">${btn('현재 내용 다시 점검','inspectAgent',{id:m.id},'wide')}${editable?btn('안전한 항목 자동 수정','repairAgent',{id:m.id},'wide'):''}</div><p class="muted" style="margin-top:12px">빈칸·중복 등 수정 가능한 항목만 자동으로 고칩니다. 내용 판단과 목표 적합성은 담당자가 확인해 주세요.</p></section><section class="card"><h3>제작·승인·배포</h3><p style="margin-top:14px">${status(m.status)}</p>${report.errors?'<p class="error">오류를 해결한 뒤 내부 검토로 넘길 수 있어요.</p>':''}<div class="actions">${m.status==='draft'?btn('내부 검토로 넘기기','requestReview',{id:m.id},'primary wide'):m.status==='approved'?link('기관 배포 설정','distribution',{id:m.id},'primary wide'):m.status==='published'?btn('새 버전 만들기','newVersion',{id:m.id,subject:m.key},'wide'):''}</div>${m.status==='review'?`<form data-form="approve" data-id="${m.id}" style="margin-top:16px"><div class="checklist">${['교육과정 근거 확인','내용·정답·해설 확인','학년 수준·표현 확인','설명·선행학습으로 문제 풀이 가능 · 지도안·복습 일치'].map((t,i)=>`<label class="checkrow"><input type="checkbox" name="check" value="${i}"><span>${t}</span></label>`).join('')}</div><p class="muted" style="margin-top:12px">자동 점검의 ‘확인 필요’ 항목도 검토한 뒤 승인합니다.</p><div class="actions"><button class="button primary wide" type="submit">검토 완료·배포 준비</button>${btn('수정으로 돌려보내기','returnMaterial',{id:m.id},'wide')}</div><p class="error" role="alert"></p></form>`:'<p class="muted" style="margin-top:14px">자동 점검만으로 승인되지 않습니다. 중앙 승인 후 기존 기관 수신·클래스 연결 흐름으로 이어집니다.</p>'}</section></aside>`;
}
function agentMaterialEditor(m){
 const editable=['draft','review'].includes(m.status),plan=m.agent.plan||{},source=mat(m.agent.sourceId),phases=plan.phases||[];
 const student=editable?`${field('자료 제목','title',m.title,'text','required maxlength="80"')}${area('학습목표','goal',m.goal,3,'required maxlength="600"')}${area('개념 설명','explanation',m.explanation,5,'required maxlength="6000"')}<details class="agent-details"><summary>예제·활동·자기 확인 편집</summary><div class="agent-question-body">${area('예제 문제 또는 대화','examplePrompt',m.workedExample?.prompt,3,'maxlength="2000"')}${area('풀이 단계 또는 대화 내용 · 한 줄에 하나','exampleSteps',(m.workedExample?.steps||[]).join('\n'),5,'maxlength="5000"')}${area('예제 답 또는 표현 정리','exampleAnswer',m.workedExample?.answer,2,'maxlength="2000"')}${field('활동 제목','activityTitle',m.activity?.title,'text','maxlength="200"')}${field('준비물','activityMaterials',m.activity?.materials,'text','maxlength="500"')}${area('활동 순서 · 한 줄에 하나','activitySteps',(m.activity?.steps||[]).join('\n'),4,'maxlength="4000"')}${area('한 걸음 더','extension',m.extension,3,'maxlength="2000"')}${area('자기 확인 · 한 줄에 하나','selfCheck',(m.selfCheck||[]).join('\n'),3,'maxlength="2000"')}</div></details><div class="divider"></div><h3>복습 ${m.questions.length}문항</h3><p class="muted" style="margin:10px 0">문항을 펼쳐 선택지·정답·힌트·해설을 수정할 수 있어요.</p>${m.questions.map(agentQuestionEditor).join('')}<div class="actions"><button class="button primary" type="submit">변경 저장·다시 점검</button>${btn('학생용 교재 미리보기','previewAgentStudent',{id:m.id})}</div><p class="error" role="alert"></p>`:`<h3>오늘의 목표</h3><p class="bodycopy" style="margin:12px 0 24px">${esc(m.goal)}</p><h3>개념 설명</h3><p class="bodycopy" style="margin-top:12px">${esc(m.explanation)}</p>${learningExtras(m)}${materialQuestions(m)}`;
 const guide=`<section class="agent-plan"><h3>수업 시간 배분 · ${m.duration}분</h3><div class="agent-phases">${phases.map(p=>`<div><span>${esc(p.minutes)}분</span><strong>${esc(p.title)}</strong><p>${esc(p.activity)}</p></div>`).join('')}</div>${(plan.prerequisites||[]).length?`<h3>먼저 확인할 개념</h3><ul class="lesson-list">${plan.prerequisites.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}${plan.focus?`<p class="bodycopy">${esc(plan.focus)}</p>`:''}${plan.coverageNote?`<p class="muted">${esc(plan.coverageNote)}</p>`:''}</section><div class="divider"></div>${editable?`${area('튜터 지도안','guide',m.guide,12,'required maxlength="12000"')}${area('성취기준·근거 메모','criterion',m.criterion,3,'maxlength="2000"')}<button class="button" type="submit">지도안과 교재 함께 저장</button>`:`<h3>튜터 지도안</h3><p class="bodycopy" style="margin:14px 0">${esc(m.guide)}</p>`}<div class="divider"></div><h3>제작 근거</h3><p class="bodycopy" style="margin:12px 0">${esc(m.agent.sourceTitle)} · v${esc(m.agent.sourceVersion)}<br>${esc((m.standards||[]).join(' · '))}</p><p class="muted">초등 5학년 · ${esc(m.subject)} · ${esc(m.agent.input?.level||'기본')}<br>수록 자료 기반 자동 구성. 공식 교육과정 적합성 인증을 뜻하지 않습니다.</p>${source?link('참고한 원본 보기','material',{id:source.id},'small'):''}<div style="margin-top:15px">${curriculumInfo(m)}</div>`;
 return head(m.status==='review'?'교재 꾸러미 · 중앙 내부 검토':'교재 꾸러미',`${m.subject} · ${m.unit} · ${m.duration}분 · 복습 ${m.questions.length}문항`,link('새 꾸러미 만들기','agent',{source:m.agent.sourceId},'ghost'))+workflowPanel(m)+`<div class="agent-result-heading"><div class="row">${status(m.status)}${badge('수록 자료 기반 자동 구성','purple')}${badge('v'+m.version,'gray')}</div><p class="muted">${editable?'내용을 수정한 뒤 저장하면 자동 점검을 다시 실행합니다. 중앙 검토 확인은 초기화됩니다.':'확정된 원본입니다. 내용을 바꾸려면 새 버전을 만들어 주세요.'}</p></div><div class="agent-output-grid">${editable?`<form class="agent-edit-form" data-form="editAgentMaterial" data-id="${m.id}">`:''}<section class="card agent-student"><div class="cardhead"><h2>학생용 교재</h2>${badge(m.subject)}</div>${student}</section><section class="card agent-guide"><div class="cardhead"><h2>튜터 지도안</h2>${badge(m.duration+'분','green')}</div>${guide}</section>${editable?'</form>':''}${agentReviewPanel(m)}</div>`;
}
function agentEditPayload(form){
 const f=new FormData(form),m=mat(form.dataset.id),get=k=>String(f.get(k)??''),lines=k=>get(k).split('\n').map(s=>s.trim()).filter(Boolean);
 return {materialId:m.id,title:get('title'),goal:get('goal'),explanation:get('explanation'),guide:get('guide'),criterion:get('criterion'),workedExample:{prompt:get('examplePrompt'),steps:lines('exampleSteps'),answer:get('exampleAnswer')},activity:{title:get('activityTitle'),materials:get('activityMaterials'),steps:lines('activitySteps')},extension:get('extension'),selfCheck:lines('selfCheck'),questions:m.questions.map((q,i)=>({...q,text:get('q'+i+'_text'),options:q.options.map((_,j)=>get('q'+i+'_option'+j)),answer:get('q'+i+'_answer')===''?null:Number(get('q'+i+'_answer')),hint:get('q'+i+'_hint'),feedback:get('q'+i+'_feedback')}))};
}
function saveVisibleAgentForm(){const form=$('form[data-form="editAgentMaterial"]');if(!form)return true;if(!form.reportValidity())return false;const p=agentEditPayload(form),m=mat(p.materialId);if(Object.entries(p).every(([k,v])=>k==='materialId'||JSON.stringify(v)===JSON.stringify(m[k])))return true;return !!commit('editMaterial',p,'',form.querySelector('.error'));}
function previewAgentStudent(m){dialog('학생용 교재 미리보기',`<div class="row">${badge(m.subject)}${badge('검토 전 미리보기','orange')}</div><h2 style="margin:20px 0">${esc(m.title)}</h2><h3>오늘의 목표</h3><p class="bodycopy" style="margin:12px 0 24px">${esc(m.goal)}</p><h3>함께 알아봐요</h3><p class="bodycopy" style="margin-top:12px">${esc(m.explanation)}</p>${learningExtras(m)}<h3 style="margin-top:24px">복습 문제</h3><p class="muted">정답과 해설은 학생이 풀고 확인할 때 제공됩니다.</p>${m.questions.map((q,i)=>`<div class="agent-question"><strong>${i+1}. ${esc(q.text)}</strong><ol class="lesson-list">${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol></div>`).join('')}`);}

function centralMaterials(){const items=state.materials,filtered=materialFilterData(items).list;return head('공통 학습자료 제작','학생 자료·튜터 지도안·복습 문제를 중앙에서 함께 만듭니다.',`<div class="actions">${link('교재 꾸러미 만들기','agent',{},'primary')}${link('5학년 1학기 자료','semester')}${btn('기존 예시 초안','newMaterial')}</div>`)+`<section class="agent-intro"><div><span class="eyebrow">차시별 교재 제작·검수</span><h2>목표를 정하면, 수업 한 차시가 한 꾸러미로.</h2><p>꾸러미 = 학생용 교재 + 복습 문제 + 튜터 지도안<br>자동 점검 결과를 확인한 뒤 중앙 검토로 넘깁니다.</p><p class="muted">수록 자료 기반 자동 구성 · 초등 5학년 수학·영어 · 외부 생성형 AI 미연결</p></div>${link('교재 에이전트 시작하기 '+icon('arrow'),'agent',{},'primary')}</section><section class="card" style="margin-top:22px">${materialFilters(items)}${filtered.length?table(['학습자료','과목·버전','상태',''],filtered.map(m=>`<tr><td class="cell-title">${esc(m.title)}${m.agent?badge('교재 에이전트','purple'):''}<small>${esc(m.goal)}</small></td><td>${m.subject} · v${m.version}</td><td>${status(m.status)}</td><td>${link(m.status==='published'?'자료·버전 보기':m.status==='review'?'내부 검토':'제작 이어가기','editor',{id:m.id},'small')}</td></tr>`)):empty('조건에 맞는 자료가 없어요','과목·단원·상태 조건을 바꾸거나 초기화해 주세요.',btn('필터 초기화','resetMaterialFilters',{context:'central'}))}</section>`;}
function materialEditor(){const m=mat(route.params.id);if(m?.agent)return agentMaterialEditor(m);if(!m)return empty('자료를 선택해 주세요','제작 목록에서 자료를 열어 주세요.',link('자료 제작','materials'));const editable=['draft','review'].includes(m.status);return head(m.status==='draft'?'공통 학습자료 만들기':m.status==='review'?'중앙 내부 검토':m.title,`${m.subject} · v${m.version} · 학생 자료 / 지도안 / 복습 문제`,link(icon('back')+' 제작 목록','materials',{},'ghost'))+workflowPanel(m)+`<div class="mainaside"><div class="stack"><section class="card"><div class="row between">${status(m.status)}${badge(m.curriculum,'gray')}</div>${editable?`<form data-form="editMaterial" data-id="${m.id}" style="margin-top:22px">${field('자료 제목','title',m.title,'text','required maxlength="80"')}${area('학습 목표','goal',m.goal,2,'required maxlength="300"')}${area('성취기준·근거 메모','criterion',m.criterion,2,'maxlength="600"')}${area('학생 자료 · 개념 설명','explanation',m.explanation,4,'required maxlength="2500"')}${area('튜터 지도안','guide',m.guide,3,'maxlength="2500"')}<button class="button" type="submit">변경 내용 저장</button><p class="muted" style="margin-top:10px">내용을 수정하면 검토 확인이 초기화되고 초안 상태로 돌아갑니다.</p><p class="error" role="alert"></p></form>`:`<h2 style="margin:23px 0 14px">${esc(m.title)}</h2><p class="bodycopy">${esc(m.goal)}</p><div class="divider"></div><p class="bodycopy">${esc(m.explanation)}</p>${learningExtras(m)}<div class="divider"></div><h3>튜터 지도안</h3><p class="bodycopy" style="margin-top:10px">${esc(m.guide)}</p>`}</section><section class="card">${materialQuestions(m)}<p class="muted" style="margin-top:18px">복습 문항은 자료에 수록된 세트로 유지됩니다. 이 화면에서는 문항 편집을 지원하지 않습니다.</p></section></div><aside class="stack"><section class="card"><h3>제작·배포 단계</h3><div class="material-steps" style="margin-top:18px">${['중앙 제작·편집','중앙 내부 검토','기관 배포·수신 확인'].map(t=>`<div class="material-step">${t}</div>`).join('')}</div><div class="actions">${m.status==='draft'?btn('내부 검토로 넘기기','requestReview',{id:m.id},'primary wide'):m.status==='approved'?link('기관 배포 설정','distribution',{id:m.id},'primary wide'):m.status==='published'?btn('새 버전 만들기','newVersion',{id:m.id,subject:m.key},'wide'):''}</div></section>${m.status==='review'?`<section class="card"><h3>검토 체크리스트</h3><form data-form="approve" data-id="${m.id}"><div class="checklist" style="margin:18px 0">${['교육과정 근거 확인','내용·정답·해설 확인','학년 수준·표현 확인','설명·선행학습으로 문제 풀이 가능 · 지도안·복습 일치'].map((t,i)=>`<label class="checkrow"><input type="checkbox" name="check" value="${i}"><span>${t}</span></label>`).join('')}</div><p class="muted">검토 절차를 체험하는 예시입니다. 실제 교과 품질 검토를 대신하지 않습니다.</p><div class="actions"><button type="submit" class="button primary wide">검토 완료·배포 준비</button>${btn('수정으로 돌려보내기','returnMaterial',{id:m.id},'wide')}</div><p class="error" role="alert"></p></form></section>`:banner('중앙에서 품질을 관리해요','검토를 마친 버전만 기관에 배포됩니다. 배포된 원본은 새 버전으로 수정합니다.')}</aside></div>`;}
function distributionView(){const ready=state.materials.filter(m=>['approved','published'].includes(m.status)),m=ready.find(x=>x.id===route.params.id)||ready.find(m=>m.status==='approved')||ready[0];return head('자료 배포와 수신 현황','중앙에서 만든 자료를 기관에 전달하고 수신·사용까지 확인합니다.')+workflowPanel(m)+`<div class="mainaside"><div class="stack"><section class="card"><div class="cardhead"><h2>기관에 자료 배포하기</h2>${badge('중앙 배포')}</div>${m?`<form data-form="publish">${select('배포할 자료 버전','materialId',ready.map(m=>[m.id,`${m.title} · ${m.subject} v${m.version}`]),m.id)}<fieldset class="field" style="border:0;padding:0"><legend>배포 대상 기관</legend><div class="checklist">${state.institutions.map(i=>`<label class="checkrow"><input name="institutions" type="checkbox" value="${i.id}"><span class="grow">${esc(i.name)}<small>${i.region}</small></span></label>`).join('')}</div></fieldset><p class="muted">즉시 배포하는 예시입니다. 기관 수신 확인과 클래스 적용은 각각 별도 단계로 기록합니다.</p><div class="actions"><button type="submit" class="button primary">${icon('send')} 선택한 기관에 배포</button></div><p class="error" role="alert"></p></form>`:empty('배포할 자료가 없어요','자료를 만들고 중앙 내부 검토를 마쳐 주세요.',link('자료 제작','materials',{},'primary'))}</section><section class="card"><h2 style="margin-bottom:20px">기관별 수신·사용</h2>${table(['자료','기관','수신','사용'],state.deliveries.map(d=>{const mm=mat(d.materialId);return `<tr><td class="cell-title">${esc(mm.title)}<small>${mm.subject} · v${mm.version}</small></td><td>${esc(institution(d.institution))}</td><td>${badge(d.received?'확인 완료':'미수신',d.received?'green':'orange')}</td><td>${state.classes.filter(c=>c.institution===d.institution&&c.materialId===d.materialId).length}개 클래스</td></tr>`;}))}</section></div><aside class="stack">${banner('배포와 사용을 구분해요','자료를 배포하면 기관의 배포 자료함에 도착합니다. 기관이 수신 확인 후 클래스에 연결합니다.')}<section class="card"><h3>미수신 후속 지원</h3><p class="subline">기관이 자료를 받지 못했다면 전달 경로와 접속 상황을 확인해 주세요.</p><div class="actions">${btn('지원 요청 등록','newSupport',{central:'true'},'wide')}</div></section></aside></div>`;}
function supportView(central){const list=state.supports.filter(s=>central?s.central:s.institution===scope),s=list.find(s=>s.id===route.params.id);if(!s)return head(central?'기관 운영 지원':'우리 기관의 운영 지원','필요한 지원을 기록하고 조치 결과를 확인합니다.',btn(icon('plus')+' 지원 등록','newSupport',{institution:scope,central:String(central)},'primary'))+`<section class="card">${list.length?table(['지원 내용','기관·담당','상태',''],list.map(s=>`<tr><td class="cell-title">${esc(s.title)}<small>${esc(s.type)}</small></td><td>${esc(institution(s.institution))}<small>${esc(s.owner)} · ${esc(s.due)}</small></td><td>${status(s.status)}</td><td>${link('조치 확인','support',{id:s.id},'small')}</td></tr>`)):empty('진행 중인 지원이 없어요','기관에서 해결하기 어려운 내용은 중앙에 공유할 수 있어요.')}</section>`;return head(s.title,institution(s.institution)+' · '+s.type,link(icon('back')+' 목록으로','support',{},'ghost'))+`<div class="mainaside"><section class="card"><div class="row between">${status(s.status)}${badge(s.central?'중앙과 함께 지원':'기관 지원','gray')}</div><p class="bodycopy" style="margin-top:20px">${esc(s.detail||'등록된 상세 설명이 없습니다.')}</p><div class="divider"></div><h3>조치 기록</h3><div class="timeline" style="margin:20px 0">${s.log.map(t=>`<div class="timeline-item">${esc(t)}</div>`).join('')||'<p class="muted">아직 조치 기록이 없습니다.</p>'}</div><form data-form="supportUpdate" data-id="${s.id}">${area('조치 내용·다음 확인 사항','note','',3,'required maxlength="1000"')}${central?`<div class="grid cols2">${field('담당','owner',s.owner,'text','required')}${field('확인 기한','due',s.due,'text','required')}</div>`:''}${select('처리 상태','status',[['open','진행 중 · 추가 확인 필요'],['resolved','조치 완료 · 결과 확인']],s.status)}${!central&&!s.central?'<label class="checkrow"><input type="checkbox" name="central"><span>기관에서 해결하기 어려워 중앙 지원 요청</span></label>':''}<div class="actions"><button class="button primary" type="submit">조치 기록 저장</button></div><p class="error" role="alert"></p></form></section><aside>${banner('운영 조치와 학습 이해는 달라요','지원이 끝났다는 기록을 학생의 이해 완료나 성취도로 처리하지 않습니다.')}</aside></div>`;}
function askDialog(d){const m=mat(d.material);dialog('선생님께 질문해요',`<div class="context"><strong>${esc(m.title)} · ${Number(d.item)+1}번</strong><small>문제와 수업 자료가 함께 전달돼요.</small></div><form data-form="question" data-class="${d.class}" data-material="${m.id}" data-item="${d.item}" style="margin-top:22px"><fieldset class="field" style="border:0;padding:0"><legend>어디에서 막혔나요?</legend><div class="checklist">${['문제 뜻이 어려워요','풀이가 헷갈려요','내 답을 봐주세요'].map((t,i)=>`<label class="checkrow"><input name="category" type="radio" value="${t}" ${i===0?'checked':''}><span>${t}</span></label>`).join('')}</div></fieldset>${area('조금 더 설명하고 싶다면','text','',3,'maxlength="1000" placeholder="한 줄만 적어도 괜찮아요."')}<button type="submit" class="button primary wide">질문 보내기 ${icon('send')}</button></form>`);}
function previewMaterial(m){dialog(m.title,`<div class="row between">${badge(m.subject)}${badge('중앙 배포 v'+m.version,'green')}</div><p class="bodycopy" style="margin:20px 0">${esc(m.goal)}</p><h3>학생 자료</h3><p class="bodycopy" style="margin:12px 0 22px">${esc(m.explanation)}</p>${learningExtras(m)}<h3>튜터 지도안</h3><p class="bodycopy" style="margin:12px 0 22px">${esc(m.guide)}</p>${materialQuestions(m)}`);}
function assignDialog(materialId,classId){const cs=classesFor('institution').filter(c=>c.status==='scheduled'&&(!materialId||c.subject===mat(materialId).key)&&(!classId||c.id===classId)),ms=state.materials.filter(m=>m.status==='published'&&state.deliveries.some(d=>d.materialId===m.id&&d.institution===scope&&d.received)&&(!classId||state.classes.find(c=>c.id===classId)?.subject===m.key)&&(!materialId||m.id===materialId));dialog('수업에 공통 자료 연결',cs.length&&ms.length?`<form data-form="assignMaterial">${select('클래스','classId',cs.map(c=>[c.id,`${c.name} · ${c.slot}`]),classId||cs[0].id)}${select('중앙 배포 자료','materialId',ms.map(m=>[m.id,`${m.title} v${m.version}`]),materialId||ms[0].id)}<p class="muted">아직 시작하지 않은 수업에 연결합니다. 기존 질문은 작성 당시 자료를 계속 참조합니다.</p><div class="actions"><button class="button primary wide" type="submit">자료 연결하기</button></div></form>`:empty('연결 조건을 확인해 주세요',!cs.length?'같은 과목의 아직 시작하지 않은 클래스가 필요해요. 먼저 클래스를 만들어 주세요.':'중앙이 배포하고 기관이 수신 확인한 같은 과목 자료가 필요해요.',!cs.length?link('클래스 만들기','matching',{},'primary'):btn('배포 자료·수신 확인','institutionMaterials',{},'primary')));}

function learningRecap(m){const support=E.learningSupport(state,m);if(!support.concepts.length)return '';const resume=route.role==='student'&&['review','practice'].includes(route.view)?path('student',route.view,route.params):'';return `<section class="learning-recap" aria-label="문제 전 개념 복습"><h3>풀기 전에 잠깐 복습</h3><ul>${support.concepts.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${support.prerequisites.length?`<details><summary>관련 개념을 더 살펴볼까요?</summary><div class="actions">${support.prerequisites.map(m=>link(m.title,'material',{id:m.id,...(resume?{resume}:{})},'small')).join('')}</div></details>`:''}</section>`;}
function documentNeedsReview(t){return t?.document?.status==='pending'||t?.document?.status==='approved'&&!t.document.demo&&t.document.reviewVersion!==2;}
function documentStatus(t){return t?.document?.status==='approved'&&!t.document.demo&&t.document.reviewVersion!==2?'확인 절차 재검토 필요':documentLabels[t?.document?.status]||'미제출';}
function documentProcedure(){return `<details class="document-guide"><summary>필요한 서류와 확인 절차</summary><p><strong>확인 목적: 성범죄·아동학대 관련 취업제한 여부 확인</strong></p><p>성범죄와 아동학대 관련 확인을 함께 진행할 때 사용하는 공식 서류는 ‘성범죄 경력 및 아동학대관련범죄 전력 조회 회신서’입니다. 기관 유형에 따라 개별 회신서로 확인하는 경우도 있습니다.</p><ol><li><strong>기관 적용 요건 확인:</strong> 소속 기관이 법령 적용 대상과 조회 권한, 참여 형태에 맞는 절차를 먼저 확인합니다.</li><li><strong>본인 동의·조회:</strong> 기관이 대상자의 동의를 받아 경찰청 시스템이나 관할 경찰서에 조회를 요청합니다. 적법한 본인 신청·회신서 제출 경로를 이용하는 경우 기관 안내를 따릅니다.</li><li><strong>회신 확인:</strong> 담당자가 확인 목적에 맞는 공식 회신서와 대상자·기관·발급정보 및 성범죄·아동학대 관련 취업제한 해당 여부를 확인합니다.</li><li><strong>기관 확인 완료:</strong> 확인 항목과 담당자 의견을 기록한 뒤 매칭 참여 여부를 확인합니다.</li></ol><p><strong>본인확인용 범죄·수사경력회보서는 기관 제출용으로 사용할 수 없습니다.</strong></p><p><a href="https://crims.police.go.kr/main.do" target="_blank" rel="noopener noreferrer">경찰청 범죄경력회보서 발급시스템 안내</a></p><p class="muted">이 프로토타입에서는 실제 조회나 동의를 진행하지 않습니다. 실제 개인정보·회신서 대신 체험용 파일만 사용해 주세요.</p></details>`;}
function learningExtras(m){const recap=learningRecap(m);if(!m.workedExample)return recap;return recap+`<section class="lesson-section"><h3>${m.key==='english'?'함께 읽는 대화':'차근차근 풀어 보는 예제'}</h3><div class="context"><strong>${esc(m.workedExample.prompt)}</strong><ol class="lesson-list">${m.workedExample.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="bodycopy">${esc(m.workedExample.answer)}</p></div></section><section class="lesson-section"><h3>${esc(m.activity.title)}</h3><p class="muted">준비물: ${esc(m.activity.materials)}</p><ol class="lesson-list">${m.activity.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></section><section class="lesson-section"><h3>한 걸음 더</h3><p class="bodycopy">${esc(m.extension)}</p></section><section class="lesson-section"><h3>스스로 확인해요</h3><ul class="lesson-list">${m.selfCheck.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section>`;}
function curriculumInfo(m){return `<details class="curriculum-info"><summary>교육과정 근거와 자료 정보</summary><p class="bodycopy">${esc(m.curriculum)}<br>${esc((m.standards||[]).join(' · '))}<br>${esc(m.criterion)}</p><p class="muted">${esc(m.publicationNote||'')} · 근거 확인 ${esc(m.curriculumChecked||'2026-11-02')}<br>5~6학년군 성취기준을 5학년 1학기 보충학습으로 재구성했습니다. 영어 주제 순서는 학교 교과서에 맞춰 조정하세요.</p><ul class="lesson-list">${(m.sources||E.sources).map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a></li>`).join('')}</ul></details>`;}
function semesterLibrary(){const key=route.params.subject==='english'?'english':'math',unit=route.params.unit||'',all=[...state.materials.filter(m=>m.catalogId===E.catalogId&&m.key===key&&m.status==='published').reduce((byProgram,m)=>{const old=byProgram.get(m.program);if(!old||Number(m.version)>Number(old.version))byProgram.set(m.program,m);return byProgram;},new Map()).values()].sort((a,b)=>a.week-b.week),units=[...new Set(all.map(m=>m.unit))],list=all.filter(m=>!unit||m.unit===unit);return head('5학년 1학기 학습자료','2022 개정 교육과정 · 18주 · 과목별 주 1회 40분 보충학습')+`<section class="semester-intro"><div><span class="eyebrow">함께 배우는 한 학기</span><h2>수학 18차시 · 영어 18차시</h2><p>개념부터 활동, 복습까지 한 자료로 이어가요.<br>두 과목 총 36차시 · 복습 180문항 · 정답과 해설 포함</p></div>${bookArt}</section><div class="tabs" aria-label="학기 자료 과목">${['math','english'].map(k=>link(E.lessons[k].subject,'semester',{subject:k},key===k?'active':'')).join('')}</div><form data-form="semesterFilter" class="semester-filter">${select('단원 선택','unit',[['','전체 단원'],...units.map(u=>[u,u])],unit)}<input type="hidden" name="subject" value="${key}"><button type="submit" class="button">단원 보기</button><span class="muted">${list.length}차시 / ${all.length}차시</span></form><p class="muted" style="margin:0 0 20px">${key==='math'?'혼합 계산 → 약수와 배수 → 대응 관계 → 약분과 통분 → 분수의 덧셈과 뺄셈 → 다각형의 둘레와 넓이':'듣기·말하기·읽기·쓰기를 함께 연습해요. 듣기는 튜터가 자료 속 대본을 읽어 주는 활동입니다.'} 정규 수업의 전체 시수가 아닌 주 1회 보충 과정입니다.</p><div class="grid cols2">${list.map(m=>{const correct=new Set(state.attempts.filter(a=>a.student===activeStudent&&a.materialId===m.id&&a.correct).map(a=>a.item)).size;return `<section class="card semester-card"><div class="row between">${badge(m.week+'주차 · '+m.duration+'분',key==='english'?'purple':'')}${badge(m.unit,'gray')}</div><h2>${esc(m.title)}</h2><p class="muted">${esc(m.goal)}</p><p class="muted">${m.questions.length}문항${route.role==='student'?' · 맞혀 본 문제 '+correct+'/'+m.questions.length:''}</p><div class="actions">${link('학습자료 열기 '+icon('arrow',16),'material',{id:m.id},'primary')}${route.role==='student'?link('바로 연습','practice',{material:m.id}):route.role==='institution'?btn('클래스에 연결','assignMaterial',{id:m.id}):''}</div></section>`;}).join('')||empty('이 단원에 자료가 없어요','전체 단원에서 다시 찾아보세요.',link('전체 단원','semester',{subject:key}))}</div>`;}
function semesterDetail(){const m=mat(route.params.id);if(!m||m.catalogId!==E.catalogId)return empty('학습자료를 선택해 주세요','학기 자료에서 차시를 선택해요.',link('학기 자료','semester'));return head(m.title,`초등 5학년 1학기 · ${m.week}주차 · ${m.unit} · ${m.duration}분`,(route.role==='student'&&/^student\/(review|practice)\?/.test(route.params.resume||'')?`<button class="button primary" data-go="${esc(route.params.resume)}">${icon('back')} 풀던 문제로 돌아가기</button>`:link(icon('back')+' 학기 자료','semester',{subject:m.key},'ghost')))+`<div class="mainaside"><div class="stack"><section class="card"><div class="row between">${badge(m.subject)}${badge('학기 자료 v'+m.version,'green')}</div><h2 style="margin:22px 0 12px">오늘의 목표</h2><p class="bodycopy">${esc(m.goal)}</p><div class="divider"></div><h3>함께 알아봐요</h3><p class="bodycopy" style="margin-top:12px">${esc(m.explanation)}</p>${learningExtras(m)}<div class="actions">${route.role==='student'?link('5문제 연습하기 '+icon('arrow'),'practice',{material:m.id},'primary'):route.role==='institution'?btn('클래스에 연결','assignMaterial',{id:m.id},'primary'):''}</div></section><section class="card">${materialQuestions(m)}</section>${route.role!=='student'?`<section class="card"><h2>튜터 지도안 · 40분 수업</h2><p class="bodycopy" style="margin-top:15px">${esc(m.guide)}</p></section>`:''}</div><aside class="stack"><section class="card"><h3>이번 차시의 순서</h3><div class="material-steps" style="margin-top:15px">${['목표와 개념 확인','예제 함께 풀기','직접 활동하기','5문제 복습과 자기 확인'].map(t=>`<div class="material-step">${t}</div>`).join('')}</div></section><section class="card">${curriculumInfo(m)}</section>${route.role==='central'?link('원본·새 버전 관리','editor',{id:m.id},'wide'):''}</aside></div>`;}

function choices(label,name,values,selected=[]){return `<fieldset class="field" style="border:0;padding:0"><legend>${esc(label)}</legend><div class="checklist">${values.map(v=>`<label class="checkrow"><input type="checkbox" name="${name}" value="${esc(v)}" ${selected.includes(v)?'checked':''}>${esc(v)}</label>`).join('')}</div></fieldset>`;}
function profileFields(x={},tutor=false){return choices('가능 시간','slots',E.matchSlots,x.slots||[])+select('우선 희망 시간','preferredSlot',E.matchSlots.map(v=>[v,v]),x.preferredSlot||E.matchSlots[0])+(tutor?choices('지도 경험·가능 영역','skills',E.needs,x.skills||[])+choices('제공 가능한 지도 방식','styles',E.styles,x.styles||[])+`<div class="grid cols2">${field('연속 활동 가능 기간 (주)','weeks',x.weeks||18,'number','required min="1" max="52"')}${field('최대 담당 학생 수','maxStudents',x.maxStudents||4,'number','required min="1" max="40"')}</div>`:select('학습 목표','need',E.needs.map(v=>[v,v]),x.need)+select('희망 지도 방식','style',E.styles.map(v=>[v,v]),x.style)+select('현재 진도 수준','level',['기초','기본','심화'].map(v=>[v,v]),x.level)+field('대기 시작일','waitingSince',x.waitingSince||'2026-11-03','date','required')+`<label class="checkrow"><input type="checkbox" name="interrupted" ${x.interrupted?'checked':''}>기존 수업 중단으로 재배정 필요</label>`);}
function uploadField(){return `<div class="field"><label for="document-file">취업제한 확인용 회신서 예시 첨부</label><p class="muted">성범죄 경력 및 아동학대관련범죄 전력 조회 회신서 · 본인확인용 회보서는 제출할 수 없습니다.</p><input id="document-file" type="file" name="document" accept="application/pdf,image/jpeg,image/png"><p class="muted">체험용 PDF·JPG·PNG · 최대 10MB. 실제 개인정보·회신서는 첨부하지 마세요. 이 브라우저에만 저장됩니다.</p><p class="muted" id="file-selection" aria-live="polite">선택한 파일이 없습니다.</p>${documentProcedure()}</div>`;}
const documentLabels={missing:'미제출',pending:'검토 대기',approved:'확인 완료',rejected:'보완 요청'};
function tutorRegistration(){const t=state.tutors.find(t=>t.id===activeTutor);return head('튜터 가입·서류','활동 정보와 성범죄·아동학대 관련 취업제한 확인 절차를 살펴보세요.')+`<div class="mainaside"><section class="card"><h2>새 튜터 가입 신청</h2><p class="subline">초등 5학년 수학·영어 프로그램</p><form data-form="registerTutor">${field('이름','name','','text','required maxlength="40"')}${select('활동 기관','institution',state.institutions.map(i=>[i.id,i.name]),scope)}${choices('지도 과목','subjects',['math','english']).replace(/>math</g,'>수학<').replace(/>english</g,'>영어<')}${profileFields({},true)}${uploadField()}<p class="muted">서류는 가입 후에도 제출할 수 있어요. 기관 확인 완료 후 매칭 후보에 포함됩니다.</p><p class="error" role="alert"></p><button class="button primary" type="submit">가입 신청하기</button></form></section><aside class="stack"><section class="card"><h2>${esc(t?.name)}님의 제출 현황</h2><p style="margin:16px 0">${badge(documentStatus(t),t?.verified?'green':'orange')}</p><p class="muted">${esc(t?.document?.name|| (t?.document?.demo?'예시 서류 상태 · 실제 첨부 없음':'아직 첨부한 서류가 없어요.'))}</p>${t?.document?.note?`<p class="bodycopy">기관 의견: ${esc(t.document.note)}</p>`:''}${t?.document?.id?btn('첨부 파일 열기','openDocument',{id:t.id}):''}<form data-form="submitDocument">${uploadField().replaceAll('document-file','replacement-file').replaceAll('file-selection','replacement-selection')}<p class="error" role="alert"></p><button type="submit" class="button">서류 제출·교체하기</button></form><p class="muted">교체하면 기관의 재확인이 필요합니다.</p></section><section class="card"><h3>내 매칭 정보</h3><p class="muted">가능 시간·지도 경험·활동 기간을 최신 상태로 관리해 주세요.</p>${btn('내 정보 수정','matchProfile',{id:activeTutor,kind:'tutor'})}</section></aside></div>`;}
function matchingView(){if(route.params.id)return manualMatchingView();const drafts=state.proposals.filter(d=>d.institution===scope&&d.status==='pending'),wait=state.matchWait.filter(w=>w.institution===scope),tutors=state.tutors.filter(t=>t.institution===scope);return head('자동매칭과 기관 승인','필수조건을 통과한 후보를 추천하고, 기관 담당자가 최종 확정합니다.',btn('자동매칭안 만들기','generateMatches',{},'primary'))+`<div class="stack"><section class="card"><h2>추천 기준</h2><p class="bodycopy">학습 필요·지도 역량 35 · 지속 참여 25 · 선호 시간 20 · 지도 방식 10 · 담당 여력 10점</p><p class="muted">초기 운영 배점입니다. 수업 중단 → 대기 시작일 → 가능한 후보 수 순으로 배정을 검토합니다. 승인 대기안끼리도 같은 시간과 장소를 우선 예약해 중복을 줄입니다.</p></section><section class="card"><h2>승인 대기 ${drafts.length}건</h2>${drafts.map(d=>`<article class="context" style="margin-top:16px"><h3>${esc(person(d.student))} · ${esc(E.lessons[d.subject].subject)}</h3><form data-form="reviewMatch" data-id="${d.id}">${select('추천 후보 · 순위는 생성 시점 기준','selected',d.options.map((o,i)=>[String(i),`${i+1}. ${person(o.tutor)} · ${o.score}점 · ${o.slot} · ${o.room}`]),String(d.selected))}${d.options.map((o,i)=>`<details ${i===0?'open':''}><summary>${i+1}순위 추천 이유 · ${esc(person(o.tutor))}</summary><p class="muted">${esc(o.note)}<br>${o.parts.map(([name,n])=>esc(name)+' '+n+'점').join(' · ')}</p></details>`).join('')}<label class="checkrow"><input name="checked" type="checkbox">학생·튜터의 참여 의사, 활동 기간과 학습 목표를 확인했습니다.</label>${field('반려 시 사유','note','','text','maxlength="200"')}<p class="error" role="alert"></p><div class="actions"><button class="button primary" name="decision" value="approved" type="submit">기관 최종 승인</button><button class="button" name="decision" value="rejected" type="submit">반려</button></div></form></article>`).join('')||'<p class="subline">자동매칭안 만들기를 누르면 미배정 학생의 후보를 검토합니다.</p>'}</section>${wait.length?`<section class="card"><h2>매칭 대기·정보 보완</h2>${wait.map(w=>rowItem(person(w.student)+' · '+E.lessons[w.subject].subject,w.reason,btn('학생 정보 수정','matchProfile',{id:w.student,kind:'student'},'small'))).join('')}</section>`:''}<section class="card"><h2>튜터 자격·서류 검토</h2>${tutors.map(t=>rowItem(t.name,`${documentStatus(t)}${t.document?.demo?' · 예시 상태':''} · ${t.document?.name||'첨부 파일 없음'}`,`<div class="actions">${btn('매칭 정보','matchProfile',{id:t.id,kind:'tutor'},'small')}${btn('서류 검토','reviewTutor',{id:t.id},'small')}</div>`)).join('')}</section><section class="card"><h2>학생 매칭 정보</h2>${state.students.filter(k=>k.institution===scope).map(k=>rowItem(k.name,`${k.need||'목표 미입력'} · ${k.slots?.join(', ')||'시간 미입력'}`,btn('수정','matchProfile',{id:k.id,kind:'student'},'small'))).join('')}</section><details class="card"><summary>직접 구성·기존 클래스 변경</summary>${manualMatchingView()}</details><details class="card"><summary>승인·반려 이력</summary>${state.proposals.filter(d=>d.institution===scope&&d.status!=='pending').map(d=>rowItem(person(d.student)+' · '+E.lessons[d.subject].subject,d.status==='approved'?'기관 승인 완료':`반려: ${d.note}`,badge(d.status==='approved'?'승인':'반려'))).join('')||'<p>아직 처리한 매칭안이 없어요.</p>'}</details></div>`;}
async function attachmentStore(action,key,value){return new Promise((resolve,reject)=>{const request=indexedDB.open('pogeun-attachments',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onerror=()=>reject(new Error('첨부 저장 공간을 열 수 없습니다.'));request.onsuccess=()=>{const db=request.result,tx=db.transaction('files',action==='get'?'readonly':'readwrite'),store=tx.objectStore('files');const q=action==='put'?store.put(value,key):action==='clear'?store.clear():action==='delete'?store.delete(key):store.get(key);let result;q.onsuccess=()=>{result=q.result;};tx.oncomplete=()=>{db.close();resolve(result);};tx.onerror=()=>{db.close();reject(new Error('파일 저장에 실패했습니다. 저장 공간을 확인해 주세요.'));};};});}
async function prepareAttachment(file){if(!file?.name)return null;if(!file.size)throw new Error('빈 파일은 첨부할 수 없습니다.');const d={id:crypto.randomUUID?crypto.randomUUID():'doc-'+Date.now(),name:file.name,type:file.type,size:file.size};E.validateDocument(d);const b=new Uint8Array(await file.slice(0,8).arrayBuffer());const valid=file.type==='application/pdf'?String.fromCharCode(...b.slice(0,5))==='%PDF-':file.type==='image/png'?[137,80,78,71,13,10,26,10].every((v,i)=>b[i]===v):b[0]===255&&b[1]===216&&b[2]===255;if(!valid)throw new Error('파일 형식과 내용이 일치하지 않습니다. PDF·JPG·PNG 파일을 확인해 주세요.');await attachmentStore('put',d.id,file);return d;}
function profilePayload(f){const p=Object.fromEntries(f);return {...p,slots:f.getAll('slots'),skills:f.getAll('skills'),styles:f.getAll('styles'),subjects:f.getAll('subjects'),interrupted:f.has('interrupted')};}

const SESSION_KEY='pogeun-session-v1';
let authSession=readSession();
function readSession(){try{const a=JSON.parse(sessionStorage.getItem('pogeun-session-v1'));if(a?.demo&&menus[a.role])return a;const account=state.accounts?.find(x=>x.email===a?.email&&x.personId===a?.personId&&x.role===a?.role);return account?{email:account.email,role:account.role,personId:account.personId,institution:account.institution}:null;}catch{return null;}}
function startSession(account){authSession=account;try{sessionStorage.setItem(SESSION_KEY,JSON.stringify(account));}catch{}if(account.role==='student')activeStudent=account.personId||'s1';if(account.role==='tutor')activeTutor=account.personId||'t1';scope=account.institution||'ga';}
function endSession(){clearTimeout(toast.timer);$('#toast').classList.remove('show');authSession=null;try{sessionStorage.removeItem(SESSION_KEY);}catch{}closeModal();location.hash='auth/login';render();}
function authView(){const signup=location.hash.startsWith('#auth/signup'),kind=new URLSearchParams(location.hash.split('?')[1]||'').get('kind')==='tutor'?'tutor':'student';document.body.className='auth-page';document.title='포근동행 · '+(signup?'회원가입':'로그인');$('#app').innerHTML=`<main id="main" tabindex="-1" class="auth-shell"><section class="auth-story"><a class="brand" href="#auth/login"><span class="brand-icon">${icon('heart',23)}</span>포근동행</a><div class="auth-story-content"><span class="auth-eyebrow">함께 배우는 오늘</span><h1>작은 배움이 모여,<br>따뜻한 동행이 돼요.</h1><p>학생과 튜터가 만나고,<br>기관 선생님이 배움의 여정을 함께합니다.</p>${bookArt}<div class="auth-points"><span>${icon('book',18)} 나에게 맞는 배움</span><span>${icon('users',18)} 함께하는 튜터</span><span>${icon('heart',18)} 기관의 든든한 지원</span></div></div><p class="auth-caption">초등 5학년 · 수학과 영어</p></section><section class="auth-panel"><div class="auth-form-wrap"><nav class="auth-tabs" aria-label="계정 메뉴"><a href="#auth/login" ${!signup?'aria-current="page"':''}>로그인</a><a href="#auth/signup" ${signup?'aria-current="page"':''}>회원가입</a></nav><h2>${signup?'포근동행에 오신 걸 환영해요':'다시 만나 반가워요'}</h2><p class="subline">${signup?'참여 유형을 선택하고 함께 배움을 시작해 보세요.':'로그인하고 오늘의 배움을 이어가세요.'}</p>${signup?`<div class="auth-kinds"><a href="#auth/signup?kind=student" class="${kind==='student'?'selected':''}">${icon('book')} 학생·보호자</a><a href="#auth/signup?kind=tutor" class="${kind==='tutor'?'selected':''}">${icon('users')} 튜터</a></div>`:''}<form data-form="${signup?'authSignup':'authLogin'}" data-kind="${kind}">${signup?field(kind==='student'?'학생 이름':'이름','name','','text','required maxlength="40" autocomplete="name"'):''}${field('이메일','email','','email','required maxlength="254" autocomplete="username" placeholder="hello@example.com"')}<div class="auth-password">${field('비밀번호','password','','password',`required minlength="8" maxlength="128" autocomplete="${signup?'new-password':'current-password'}" ${signup?'placeholder="8자 이상 입력해 주세요"':''}`)}${btn('보기','togglePassword',{},'ghost small')}</div>${signup?field('비밀번호 확인','confirmPassword','','password','required minlength="8" maxlength="128" autocomplete="new-password"')+select('참여 기관','institution',state.institutions.map(i=>[i.id,i.name]),'ga')+(kind==='tutor'?choices('지도 과목','subjects',['math','english']).replace(/>math</g,'>수학<').replace(/>english</g,'>영어<')+profileFields({},true)+uploadField():choices('배우고 싶은 과목','subjects',['math','english']).replace(/>math</g,'>수학<').replace(/>english</g,'>영어<')+profileFields({slots:[...E.matchSlots],preferredSlot:E.matchSlots[0],need:E.needs[0],style:E.styles[0],level:'기초'},false))+`<label class="checkrow auth-agreement"><input type="checkbox" name="participation" required><span>${kind==='student'?'보호자와 함께 참여 기관·수업 내용을 확인했어요.':'기관의 자격·서류 확인 후 매칭에 참여하는 것을 확인했어요.'}</span></label>`:''}<p class="error" role="alert" aria-live="polite"></p><button type="submit" class="button primary wide">${signup?'회원가입 완료하기':'로그인'}</button></form><p class="auth-switch">${signup?'이미 계정이 있나요? <a href="#auth/login">로그인</a>':'아직 계정이 없나요? <a href="#auth/signup">회원가입</a>'}</p>${!signup?`<details class="auth-demo"><summary>가입 없이 예시 화면 체험하기</summary><p class="muted">역할별 예시 데이터로 살펴볼 수 있어요.</p><div class="auth-demo-grid">${Object.entries(roleNames).map(([role,name])=>btn(name,'demoLogin',{role})).join('')}</div></details>`:'<p class="muted">기관 담당자·중앙 운영자 계정은 운영팀에서 발급합니다.</p>'}<p class="auth-local-note">브라우저 저장형 프로토타입입니다. 테스트용 이메일·비밀번호·파일을 사용해 주세요.</p></div></section></main>`;}
async function authSubmit(form,f,kind){const submit=form.querySelector('[type=submit]'),error=form.querySelector('.error');if(submit.disabled)return;submit.disabled=true;error.textContent='';let document;
 try{const p=profilePayload(f);if(kind==='authLogin'){const account=await window.PogeunAuth.login(state.accounts||[],p.email,p.password);startSession({email:account.email,role:account.role,personId:account.personId,institution:account.institution});go('today',{},account.role);return;}
 const role=form.dataset.kind;if(!f.has('participation'))throw Error('참여 내용을 확인해 주세요.');const account=await window.PogeunAuth.createAccount(state.accounts||[],{...p,role});if(!p.name?.trim()||p.name.trim().length>40)throw Error('이름을 입력해 주세요.');if(!p.subjects.length||!p.subjects.every(x=>E.lessons[x]))throw Error('과목을 선택해 주세요.');if(!state.institutions.some(i=>i.id===p.institution))throw Error('참여 기관을 선택해 주세요.');
 let next,personId;if(role==='tutor'){document=await prepareAttachment(f.get('document'));const out=E.apply(state,'registerTutor',{...p,role,document});next=out.state;personId=out.result;}else{next=JSON.parse(JSON.stringify(state));personId='s-'+crypto.randomUUID();next.students.push({id:personId,name:p.name.trim(),institution:p.institution,consent:true,subjects:p.subjects});next=E.apply(next,'saveMatchProfile',{...p,role:'institution',institution:p.institution,kind:'student',id:personId}).state;}
 if((next.accounts||[]).some(a=>a.email===account.email))throw Error('이미 가입한 이메일입니다.');account.personId=personId;account.institution=p.institution;(next.accounts||=[]).push(account);E.save(storage,next);state=next;startSession({email:account.email,role,personId,institution:p.institution});toast(role==='tutor'?'회원가입이 완료됐어요. 기관 확인 후 매칭에 참여할 수 있어요.':'회원가입이 완료됐어요. 함께 배워요!');go(role==='tutor'?'registration':'today',{},role);
 }catch(err){if(document)await attachmentStore('delete',document.id).catch(()=>{});error.textContent=err.message;}finally{submit.disabled=false;}}
function tutorAccountView(){const t=state.tutors.find(t=>t.id===activeTutor);return head('내 정보·서류','기관의 검토 상태를 확인하고 활동 정보를 관리하세요.')+`<div class="mainaside"><section class="card"><h2>${esc(t.name)}님의 제출 현황</h2><p style="margin:16px 0">${badge(documentLabels[t.document.status],t.verified?'green':'orange')}</p><p class="bodycopy">${esc(t.document.name||'아직 첨부한 서류가 없어요.')}</p>${t.document.note?`<p>기관 의견: ${esc(t.document.note)}</p>`:''}${t.document.id?btn('첨부 파일 열기','openDocument',{id:t.id}):''}<form data-form="submitDocument">${uploadField()}<p class="error" role="alert"></p><button class="button primary" type="submit">서류 제출·교체하기</button></form></section><section class="card"><h2>내 매칭 정보</h2><p class="bodycopy">${esc(t.slots.join(' · '))}<br>${t.weeks}주 활동 가능 · 최대 ${t.maxStudents}명</p>${btn('매칭 정보 수정','matchProfile',{id:t.id,kind:'tutor'})}</section></div>`;}

document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}const target=e.target.closest('[data-go],[data-action]');if(!target)return;if(target.dataset.go){closeModal();const next='#'+target.dataset.go;if(location.hash===next)render();else location.hash=next;return;}const d=target.dataset;switch(d.action){

case 'logout':endSession();break;
case 'demoLogin':if(menus[d.role]){startSession({demo:true,role:d.role});go('today',{},d.role);}break;
case 'togglePassword':{const input=target.closest('.auth-password').querySelector('input');input.type=input.type==='password'?'text':'password';target.textContent=input.type==='password'?'보기':'숨기기';break;}
case 'generateMatches':if(commit('generateMatches',{role:route.role,institution:scope},'자동매칭안을 만들었어요. 승인 대기와 미배정 사유를 확인해 주세요.'))render();break;
case 'matchProfile':{const tutor=d.kind==='tutor',x=(tutor?state.tutors:state.students).find(x=>x.id===d.id);if(!x||!(route.role==='institution'&&x.institution===scope||tutor&&route.role==='tutor'&&x.id===activeTutor))break;dialog(x.name+' 매칭 정보',`<form data-form="saveMatchProfile" data-id="${x.id}" data-kind="${d.kind}">${profileFields(x,tutor)}<p class="error" role="alert"></p><button class="button primary" type="submit">저장하기</button></form>`);break;}
case 'reviewTutor':{const t=state.tutors.find(t=>t.id===d.id&&t.institution===scope);if(route.role!=='institution'||!t)break;dialog(t.name+' 취업제한 확인 검토',`<p>${badge(documentStatus(t))}</p><p class="bodycopy">${esc(t.document?.name||'첨부된 파일이 없습니다.')}</p>${t.document?.id?btn('첨부 파일 열기','openDocument',{id:t.id}):''}${documentProcedure()}${t.document?.demo?'<p class="muted">기존 예시 튜터의 시연 상태입니다. 실제 조회·서류 검토 기록이 아닙니다.</p>':''}${t.document?.note?`<p>기관 의견: ${esc(t.document.note)}</p>`:''}${t.document?.reviewVersion===2?`<p class="muted">기관 요건 ${t.document.reviewChecks?.institution?'확인':'미확인'} · 동의·발급 절차 ${t.document.reviewChecks?.consent?'확인':'미확인'} · 회신 내용 ${t.document.reviewChecks?.result?'확인':'미확인'}</p>`:''}${documentNeedsReview(t)?`<form data-form="reviewTutor" data-id="${t.id}" data-document="${t.document.id}"><p class="muted">아래 항목은 기관의 확인 절차를 체험하기 위한 예시입니다.</p><label class="checkrow"><input name="institutionChecked" type="checkbox">기관 유형·법령 적용 대상·조회 권한을 확인했습니다.</label><label class="checkrow"><input name="consentChecked" type="checkbox">본인 동의와 적법한 조회·발급 절차를 확인했습니다.</label><label class="checkrow"><input name="resultChecked" type="checkbox">본인확인용이 아닌 공식 회신서에서 대상자·기관·발급정보와 성범죄·아동학대 관련 취업제한 해당 여부를 확인했습니다.</label><label class="checkrow"><input name="checked" type="checkbox">확인 결과와 튜터 참여 자격을 검토했습니다.</label>${area('검토 의견·보완 사유','note','',3,'required maxlength="500"')}<div class="actions"><button class="button primary" name="decision" value="approved">확인 완료</button><button class="button" name="decision" value="rejected">보완 요청</button></div></form>`:''}`);break;}
case 'openDocument':{const t=state.tutors.find(t=>t.id===d.id);if(!t||!(route.role==='institution'&&t.institution===scope||route.role==='tutor'&&t.id===activeTutor))break;const win=window.open('about:blank','_blank');if(!win){toast('파일 열기를 위해 팝업을 허용해 주세요.');break;}win.opener=null;try{const file=await attachmentStore('get',t.document.id);if(!file)throw new Error('이 브라우저에 첨부 파일이 없습니다. 다시 제출해 주세요.');const url=URL.createObjectURL(file);win.location.replace(url);setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(err){win.close();toast(err.message);}break;}
case 'close':closeModal();break;
case 'help':dialog('포근동행 이용 도움',`<div class="stack">${banner('검토용 프로토타입이에요','모든 이름과 기록은 예시이며 같은 브라우저에만 저장됩니다. 실제 개인정보를 입력하지 마세요.')}<p>상단에서 학생·튜터·기관·중앙 운영자 역할을 바꾸며 같은 데이터가 이어지는 모습을 확인할 수 있어요.</p><p><strong>기관</strong>은 조건을 검토하고 매칭을 확정합니다.<br><strong>중앙</strong>은 학습자료를 제작·배포하고 전국 현황을 봅니다.<br><strong>튜터</strong>는 배포 자료로 수업하고 질문에 답합니다.</p>${btn('추천 체험 순서 보기','tour',{},'primary')}</div>`);break;
case 'tour':closeModal();dialog('체험할 흐름을 선택해 주세요',`<p class="muted">같은 브라우저에서 역할을 바꾸며 진행해요. 각 단계는 실제 학습·운영 기록이 생기면 완료됩니다.</p>${tourChoices()}`);break;
case 'startTour':closeModal();startTour(d.kind==='operations'?'operations':'learning');break;
case 'tourStep':tourNavigate(Number(d.index));break;
case 'stopTour':guidedTour={hidden:true};saveTour();render();break;
case 'openInstitutionMaterials':if(authSession?.demo){scope=d.id;tab='materials';go('schedule',{},'institution');}break;
case 'resetMaterialFilters':if(d.context==='institution')tab='materials';go(d.context==='institution'?'schedule':'materials');break;
case 'menu':dialog('전체 메뉴',`<nav class="stack">${nav(route.role)}</nav>`);break;
case 'reset':dialog('예시 데이터를 처음으로 돌릴까요?',`<p>이 브라우저에서 만든 매칭·질문·자료·기록이 초기 예시로 바뀝니다.</p><div class="actions">${btn('취소','close')}${btn('예시 데이터 초기화','confirmReset',{},'danger')}</div>`);break;
case 'confirmReset':guidedTour=null;saveTour();await attachmentStore('clear').catch(()=>{});state=E.seed();activeStudent='s1';activeTutor='t1';scope='ga';try{E.save(storage,state);}catch{}quiz.key='';closeModal();render();toast('초기 예시 데이터로 돌아왔어요.');break;
case 'lessonTab':tab=d.tab;render();break;
case 'lessonStart':if(commit('lesson',{classId:d.id,tutor:activeTutor,status:'active'},'수업을 시작했어요. 출석을 확인해 주세요.'))render();break;
case 'lessonFinish':dialog('수업 마무리와 복습 배정',`<form data-form="finish" data-id="${d.id}">${area('수업 메모 · 다음에 보충할 내용','notes','',4,'maxlength="1000"')}<p class="muted">수업을 마치면 동일한 자료의 공통 복습 문제가 학생에게 배정됩니다.</p><div class="actions"><button type="submit" class="button primary wide">수업 완료·복습 배정</button></div></form>`);break;
case 'choice':quiz.choice=Number(d.choice);quiz.result=null;render();break;
case 'hint':quiz.hint=true;render();break;
case 'checkAnswer':{const out=commit(route.view==='practice'?'practice':'attempt',{classId:d.class,materialId:d.material,student:activeStudent,item:quiz.index,choice:quiz.choice});if(out){quiz.result=out.result;render();}break;}
case 'nextQuestion':{const m=mat(route.params.material||findClass()?.materialId);if(quiz.index>=m.questions.length-1)quiz.done=true;else{quiz.index++;quiz.choice=null;quiz.result=null;quiz.hint=false;}render();break;}
case 'restartQuiz':quiz.index=0;quiz.choice=null;quiz.result=null;quiz.hint=false;quiz.done=false;render();break;
case 'ask':askDialog(d);break;
case 'understood':if(commit('understood',{questionId:d.id,student:activeStudent},'이해했다고 기록했어요. 다시 풀어봐요!'))render();break;
case 'reask':dialog('조금 더 물어볼까요?',`<form data-form="reask" data-id="${d.id}">${area('아직 어려운 부분','text','',3,'maxlength="1000" placeholder="비워 두면 다른 방법으로 설명해 달라고 전달해요."')}<button class="button primary wide" type="submit">다시 질문하기</button></form>`);break;
case 'previewMaterial':previewMaterial(mat(d.id));break;
case 'materialIssue':dialog('중앙에 자료 의견 전달',`<form data-form="issue" data-material="${d.material}" data-institution="${d.institution}"><p class="context">${esc(mat(d.material).title)} · v${mat(d.material).version}</p><div style="margin-top:20px">${field('어떤 내용인가요?','title','','text','required maxlength="100" placeholder="예: 2번 문항에 그림 설명을 더하면 좋겠어요."')}${area('자료 위치와 의견','detail','',4,'required maxlength="1200"')}</div><button class="button primary wide" type="submit">자료 의견 보내기</button></form>`);break;
case 'studentDetail':{const s=state.students.find(s=>s.id===d.id);dialog(s.name+' 학생',`<div class="stack">${badge(s.consent?'참여 확인 완료':'참여 확인 필요',s.consent?'green':'orange')}<p>초등 5학년 · ${esc(institution(s.institution))}<br>신청 과목: ${s.subjects.map(x=>E.lessons[x].subject).join(' · ')}</p><p class="muted">${s.consent?'기관에서 튜터·시간·정원을 검토해 매칭할 수 있어요.':'참여 절차 확인 후 매칭할 수 있어요. 이 확인 상태는 프로토타입 예시로 고정되어 있습니다.'}</p>${link('매칭 관리로','matching',{},'primary')}</div>`);break;}
case 'institutionMaterials':closeModal();tab='materials';go('schedule');break;
case 'institutionTab':tab=d.tab;render();break;
case 'receive':if(commit('receive',{materialId:d.id,institution:scope},'자료 수신을 확인했어요. 클래스에 연결해 주세요.'))render();break;
case 'assignMaterial':assignDialog(d.id,null);break;
case 'pickMaterial':assignDialog(null,d.class);break;
case 'cancelClass':dialog('수업 취소와 보강 확인',`<form data-form="cancelClass" data-id="${d.id}">${area('취소 사유·보강 검토 내용','reason','',3,'required maxlength="600"')}<p class="muted">일정을 취소 상태로 바꾸고 기관 지원 목록에 보강 확인 항목을 만듭니다.</p><div class="actions"><button class="button danger wide" type="submit">취소 기록·보강 검토</button></div></form>`);break;
case 'inspectAgent':if(saveVisibleAgentForm()&&commit('inspectMaterial',{role:route.role,materialId:d.id},'현재 교재의 자동 점검을 마쳤어요.'))render();break;
case 'repairAgent':if(saveVisibleAgentForm()){const out=commit('repairMaterial',{role:route.role,materialId:d.id});if(out){render();toast(out.result.length?out.result.join(' · '):'자동 수정할 항목이 없습니다. 확인 필요 항목을 직접 검토해 주세요.');}}break;
case 'previewAgentStudent':if(saveVisibleAgentForm()){render();previewAgentStudent(mat(d.id));}break;
case 'newMaterial':dialog('중앙에서 새 자료 만들기',`<form data-form="createMaterial">${select('과목','subject',[['math','수학 · 분수의 크기 비교'],['english','영어 · 하루 일과 말하기']],'math')}<div class="banner"><div><strong>예시 초안 불러오기</strong>실제 AI 대신 준비된 예시를 불러옵니다. 불러온 뒤 목표·설명·지도안을 편집할 수 있어요.</div></div><div class="actions"><button class="button primary wide" type="submit">예시 초안 만들기</button></div></form>`);break;
case 'newVersion':{const out=commit('createMaterial',{subject:d.subject,source:d.id},'새 버전 초안을 만들었어요.');if(out)go('editor',{id:out.result});break;}
case 'requestReview':{if(!saveVisibleAgentForm())break;const form=$('form[data-form="editMaterial"]');if(form){if(!form.reportValidity())break;const p=Object.fromEntries(new FormData(form));if(!commit('editMaterial',{...p,materialId:d.id}))break;}if(commit('reviewMaterial',{materialId:d.id},'중앙 내부 검토 단계로 이동했어요.'))render();break;}
case 'returnMaterial':if(commit('returnMaterial',{materialId:d.id},'중앙 제작 단계로 돌려보냈어요.'))render();break;
case 'newSupport':dialog('운영 지원 등록',`<form data-form="support" data-central="${d.central||'false'}">${select('기관','institution',state.institutions.filter(i=>route.role==='central'||i.id===scope).map(i=>[i.id,i.name]),d.institution||scope)}${field('지원 제목','title','','text','required maxlength="100"')}${select('지원 유형','type',[['운영 지원','운영 지원'],['접속 지원','접속 지원'],['수업 공백','수업 공백'],['자료 전달','자료 전달']],'운영 지원')}${area('지원이 필요한 내용','detail','',4,'required maxlength="1200"')}<button class="button primary wide" type="submit">지원 등록하기</button></form>`);break;
}});
document.addEventListener('change',e=>{const t=e.target;if(t.name==='filterSubject'&&t.form?.dataset.form==='materialFilters'){t.form.elements.filterUnit.value='';return;}if(t.matches('[data-agent-subject],[data-agent-unit],[data-agent-source]')){syncAgentForm(t.form,t.hasAttribute('data-agent-subject')?'subject':t.hasAttribute('data-agent-unit')?'unit':'source');return;}if(t.type==='file'){const label=t.parentElement.querySelector('[aria-live]');if(label)label.textContent=t.files[0]?t.files[0].name+' · '+(t.files[0].size/1024/1024).toFixed(2)+'MB':'선택한 파일이 없습니다.';return;}if(t.id==='persona'){if(route.role==='student')activeStudent=t.value;else activeTutor=t.value;quiz.key='';go('today');return;}if(t.id==='scope'){scope=t.value;go('today');return;}if(t.id==='national-region'){nationalRegion=t.value;render();return;}if(t.matches('[data-match-subject]')){subject=t.value;render();return;}if(t.dataset.attendance)commit('attendance',{classId:t.dataset.class,student:t.dataset.attendance,present:t.checked});});
document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const f=new FormData(form),p=Object.fromEntries(f),d=form.dataset;let out;

switch(d.form){
case 'materialFilters':{if(d.context==='institution')tab='materials';const values=Object.fromEntries(['filterSubject','filterUnit','filterStatus'].filter(k=>p[k]).map(k=>[k,p[k]]));go(d.context==='institution'?'schedule':'materials',values);break;}
case 'authLogin':case 'authSignup':await authSubmit(form,f,d.form);break;
case 'registerTutor':case 'submitDocument':{
 if(route.role!=='tutor')break;const submittingTutor=activeTutor;const buttons=[...form.querySelectorAll('button[type="submit"]')];buttons.forEach(b=>b.disabled=true);let document;
 try{document=await prepareAttachment(f.get('document'));if(d.form==='submitDocument'&&!document)throw new Error('첨부할 파일을 선택해 주세요.');const old=d.form==='submitDocument'?state.tutors.find(t=>t.id===submittingTutor)?.document?.id:null;
 const payload=d.form==='registerTutor'?{...profilePayload(f),role:'tutor',document}:{role:'tutor',actor:submittingTutor,tutor:submittingTutor,document};
 const result=E.apply(state,d.form,payload);E.save(storage,result.state);state=result.state;if(d.form==='registerTutor')activeTutor=result.result;if(old)await attachmentStore('delete',old).catch(()=>{});toast('신청을 저장했어요. 기관 확인을 기다려 주세요.');render();
 }catch(err){if(document)await attachmentStore('delete',document.id).catch(()=>{});form.querySelector('.error').textContent=err.message;buttons.forEach(b=>b.disabled=false);}break;
}
case 'saveMatchProfile':if(commit('saveMatchProfile',{...profilePayload(f),role:route.role,actor:activeTutor,institution:scope,id:d.id,kind:d.kind},'매칭 정보를 저장했어요.')){closeModal();render();}break;
case 'reviewTutor':if(commit('reviewTutor',{role:route.role,institution:scope,tutor:d.id,documentId:d.document,decision:e.submitter?.value,note:p.note,checked:f.has('checked'),institutionChecked:f.has('institutionChecked'),consentChecked:f.has('consentChecked'),resultChecked:f.has('resultChecked')},'취업제한 확인 검토 결과를 저장했어요.')){closeModal();render();}break;
case 'reviewMatch':if(commit('reviewMatch',{role:route.role,institution:scope,id:d.id,selected:p.selected,decision:e.submitter?.value,note:p.note,checked:f.has('checked')},e.submitter?.value==='approved'?'기관 승인으로 클래스가 확정됐어요.':'매칭안을 반려했어요.',form.querySelector('.error')))render();break;

case 'semesterFilter':go('semester',{subject:p.subject,...(p.unit?{unit:p.unit}:{})});break;
case 'match':out=commit('match',{classId:d.id||undefined,institution:scope,subject:state.classes.find(c=>c.id===d.id)?.subject||p.subject,tutor:p.tutor,students:f.getAll('students'),slot:p.slot,room:p.room,name:p.name},'기관에서 매칭을 확정했어요.');if(out){tab='schedule';go('schedule');}break;
case 'finish':out=commit('lesson',{classId:d.id,tutor:activeTutor,status:'completed',notes:p.notes},'수업 기록과 공통 복습을 배정했어요.');if(out){closeModal();render();}break;
case 'question':out=commit('question',{classId:d.class,materialId:d.material,item:Number(d.item),student:activeStudent,category:p.category,text:p.text},'선생님께 질문을 보냈어요.');if(out){closeModal();go('questions',{q:out.result});}break;
case 'answer':out=commit('answer',{questionId:d.id,tutor:activeTutor,text:p.answer},'답변을 보냈어요. 학생의 이해 확인을 기다려 주세요.');if(out)render();break;
case 'reask':out=commit('reask',{questionId:d.id,student:activeStudent,text:p.text},'추가 질문을 보냈어요.');if(out){closeModal();render();}break;
case 'assignMaterial':out=commit('assignMaterial',{classId:p.classId,materialId:p.materialId,institution:scope},'클래스에 공통 자료를 연결했어요.');if(out){closeModal();render();}break;
case 'cancelClass':out=commit('schedule',{classId:d.id,institution:scope,status:'cancelled'});if(out){const c=state.classes.find(c=>c.id===d.id);commit('support',{institution:scope,title:c.name+' 보강 일정 확인',type:'수업 공백',detail:p.reason,central:false},'수업 취소와 보강 검토를 기록했어요.');closeModal();render();}break;
case 'generateMaterial':{const button=e.submitter;button.disabled=true;out=commit('generateMaterial',{...p,role:route.role,variant:state.materials.filter(m=>m.agent?.sourceId===p.sourceId).length+1},'교재·문항·지도안과 자동 점검 결과를 만들었어요.',form.querySelector('.error'));if(out)go('editor',{id:out.result});else button.disabled=false;break;}
case 'editAgentMaterial':out=commit('editMaterial',agentEditPayload(form),'교재와 지도안을 저장하고 다시 점검했어요.',form.querySelector('.error'));if(out)render();break;
case 'createMaterial':out=commit('createMaterial',{subject:p.subject},'중앙의 예시 초안을 불러왔어요.');if(out){closeModal();go('editor',{id:out.result});}break;
case 'editMaterial':out=commit('editMaterial',{...p,materialId:d.id},'자료를 저장했어요. 내부 검토로 이어갈 수 있어요.');if(out)render();break;
case 'approve':{const edit=$('form[data-form="editAgentMaterial"]');if(edit){const payload=agentEditPayload(edit),current=mat(payload.materialId);if(Object.entries(payload).some(([k,v])=>k!=='materialId'&&JSON.stringify(v)!==JSON.stringify(current[k]))){if(saveVisibleAgentForm()){render();toast('편집 내용을 저장하고 초안으로 돌렸어요. 점검 후 다시 내부 검토로 넘겨 주세요.');}break;}}}out=commit('approveMaterial',{materialId:d.id,checks:[0,1,2,3].map(i=>f.getAll('check').includes(String(i)))},'검토를 마쳤어요. 기관에 배포할 수 있어요.');if(out)render();break;
case 'publish':out=commit('publish',{materialId:p.materialId,institutions:f.getAll('institutions')},'선택한 기관에 자료를 배포했어요.');if(out)render();break;
case 'issue':out=commit('support',{institution:d.institution,title:p.title,type:'자료 오류·개선',detail:`${mat(d.material).title} v${mat(d.material).version}\n${p.detail}`,central:true},'중앙 운영팀에 자료 의견을 전달했어요.');if(out){closeModal();render();}break;
case 'support':out=commit('support',{...p,central:d.central==='true'},'지원 요청을 등록했어요.');if(out){closeModal();go('support',{id:out.result});}break;
case 'supportUpdate':out=commit('supportUpdate',{...p,id:d.id,central:f.has('central')},'조치 내용을 저장했어요.');if(out)render();break;
}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',e=>{if(e.key===E.KEY){state=E.load(storage);if(authSession&&!authSession.demo&&!state.accounts?.some(a=>a.email===authSession.email)){endSession();return;}render();toast('다른 탭의 예시 데이터 변경을 반영했어요.');}});
if(authSession)startSession(authSession);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
render();
})();
